-- Contas novas já começam com o edital de 2022.
create or replace function public.semear_edital()
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  m jsonb;
  m_ordem integer := 0;
  m_id uuid;
begin
  if uid is null then
    raise exception 'É preciso estar logada para preparar o edital.';
  end if;

  insert into public.configuracoes (user_id) values (uid) on conflict (user_id) do nothing;

  if (select edital_semeado from public.configuracoes where user_id = uid)
     or exists (select 1 from public.materias where user_id = uid) then
    update public.configuracoes set edital_semeado = true where user_id = uid and not edital_semeado;
    return;
  end if;

  for m in select * from jsonb_array_elements(public.edital_tjdft_2022()) loop
    insert into public.materias (user_id, nome, ordem, grupo)
    values (uid, m ->> 'nome', m_ordem, m ->> 'grupo')
    returning id into m_id;

    insert into public.topicos (user_id, materia_id, nome, ordem)
    select uid, m_id, t.nome, (t.ordem - 1)::integer
    from jsonb_array_elements_text(m -> 'topicos') with ordinality as t (nome, ordem);

    m_ordem := m_ordem + 1;
  end loop;

  update public.configuracoes set edital_semeado = true, edital_2022 = true where user_id = uid;
end;
$$;

-- Contas que já existiam: atualiza para o edital de 2022 sem perder nada que tenha progresso ou conteúdo.
create or replace function public.atualizar_edital_2022()
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  m jsonb;
  m_ordem integer := 0;
  m_id uuid;
  nomes text[];
  nomes_materias text[];
  velha record;
begin
  if uid is null then
    raise exception 'É preciso estar logada para atualizar o edital.';
  end if;

  insert into public.configuracoes (user_id) values (uid) on conflict (user_id) do nothing;
  if (select edital_2022 from public.configuracoes where user_id = uid) then
    return;
  end if;

  select array_agg(x ->> 'nome') into nomes_materias from jsonb_array_elements(public.edital_tjdft_2022()) as x;

  for m in select * from jsonb_array_elements(public.edital_tjdft_2022()) loop
    m_id := null;
    select id into m_id from public.materias where user_id = uid and nome = m ->> 'nome' limit 1;

    if m_id is null then
      select id into m_id from public.materias
      where user_id = uid and nome in (select jsonb_array_elements_text(m -> 'antigos'))
      limit 1;
      if m_id is not null then
        update public.materias set nome = m ->> 'nome' where id = m_id;
      end if;
    end if;

    if m_id is null then
      insert into public.materias (user_id, nome, ordem, grupo)
      values (uid, m ->> 'nome', m_ordem, m ->> 'grupo')
      returning id into m_id;
    end if;

    update public.materias set grupo = m ->> 'grupo', ordem = m_ordem where id = m_id;

    nomes := array(select jsonb_array_elements_text(m -> 'topicos'));

    -- Tira tópicos genéricos antigos que ainda não foram usados (sem status nem conteúdo ligado).
    delete from public.topicos t
    where t.materia_id = m_id
      and t.status = 'nao_visto'
      and t.nome <> all (nomes)
      and not exists (select 1 from public.bisus b where b.topico_id = t.id)
      and not exists (select 1 from public.escritas e where e.topico_id = t.id)
      and not exists (select 1 from public.erros r where r.topico_id = t.id)
      and not exists (select 1 from public.sessoes s where s.topico_id = t.id)
      and not exists (select 1 from public.resumos z where z.topico_id = t.id)
      and not exists (select 1 from public.materiais x where x.topico_id = t.id);

    insert into public.topicos (user_id, materia_id, nome, ordem)
    select uid, m_id, x.nome, (x.ordem - 1)::integer
    from unnest(nomes) with ordinality as x (nome, ordem)
    where not exists (select 1 from public.topicos t where t.materia_id = m_id and t.nome = x.nome);

    -- Ordem do edital primeiro; tópicos antigos mantidos vão para o fim.
    update public.topicos t
    set ordem = coalesce(array_position(nomes, t.nome) - 1, 1000 + t.ordem)
    where t.materia_id = m_id;

    m_ordem := m_ordem + 1;
  end loop;

  -- Matérias antigas fora do edital: some se estiverem vazias; senão ficam no fim, em "Outras matérias".
  for velha in
    select id from public.materias where user_id = uid and nome <> all (nomes_materias)
  loop
    if not exists (select 1 from public.bisus b where b.materia_id = velha.id)
       and not exists (select 1 from public.escritas e where e.materia_id = velha.id)
       and not exists (select 1 from public.erros r where r.materia_id = velha.id)
       and not exists (select 1 from public.sessoes s where s.materia_id = velha.id)
       and not exists (select 1 from public.topicos t where t.materia_id = velha.id and t.status <> 'nao_visto') then
      delete from public.materias where id = velha.id;
    else
      update public.materias set grupo = 'Outras matérias', ordem = 100 + m_ordem where id = velha.id;
      m_ordem := m_ordem + 1;
    end if;
  end loop;

  update public.configuracoes set edital_2022 = true, edital_semeado = true where user_id = uid;
end;
$$;

-- ---------------------------------------------------------------------------
-- Nomenclatura ampliada: termos de todas as matérias, ligados aos tópicos.
-- ---------------------------------------------------------------------------

create or replace function public.semear_termos_2022()
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  termos jsonb := $termos$[{"termo":"Coesão","extenso":"Coesão textual","pratica":"É a costura do texto: palavras como pronomes, conjunções e sinônimos que ligam uma frase à outra.","tecnica":"Mecanismos de referência (anáfora e catáfora), substituição, elipse e conexão por conjunções. A banca pergunta a que termo um pronome se refere ou que conectivo preserva o sentido.","dispositivo":null,"tags":["texto"],"materias":["Língua Portuguesa","Redação (prova discursiva)"],"topicos":[["Língua Portuguesa","Mecanismos de coesão textual"],["Redação (prova discursiva)","Progressão textual: coesão e coerência entre parágrafos"]]},{"termo":"Coerência","extenso":"Coerência textual","pratica":"É o texto fazer sentido do começo ao fim, sem ideias que se contradizem.","tecnica":"Relação lógica entre as ideias. Um texto pode ser coeso (bem ligado) e ainda assim incoerente.","dispositivo":null,"tags":["texto"],"materias":["Língua Portuguesa","Redação (prova discursiva)"],"topicos":[["Língua Portuguesa","Interpretação e organização interna do texto"],["Redação (prova discursiva)","Progressão textual: coesão e coerência entre parágrafos"]]},{"termo":"Anáfora","extenso":"Retomada anafórica","pratica":"É usar uma palavra para retomar algo que já apareceu antes. Ex.: \"O juiz chegou. Ele pediu silêncio.\"","tecnica":"Mecanismo de coesão referencial que retoma termo anterior (pronomes, sinônimos, hiperônimos).","dispositivo":null,"tags":["coesão"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Mecanismos de coesão textual"]]},{"termo":"Catáfora","extenso":"Antecipação catafórica","pratica":"É anunciar algo que só vem depois. Ex.: \"Só quero isto: que você passe.\"","tecnica":"Mecanismo de coesão referencial que antecipa termo posterior.","dispositivo":null,"tags":["coesão"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Mecanismos de coesão textual"]]},{"termo":"Denotação","extenso":"Sentido denotativo","pratica":"É o sentido literal, de dicionário. Ex.: \"pedra no sapato\" é uma pedra mesmo.","tecnica":"Sentido próprio, objetivo e referencial da palavra.","dispositivo":null,"tags":["semântica"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Semântica: sentido e emprego dos vocábulos e campos semânticos"]]},{"termo":"Conotação","extenso":"Sentido conotativo","pratica":"É o sentido figurado. Ex.: \"aquele processo é uma pedra no sapato\".","tecnica":"Sentido figurado, ampliado pelo contexto. Comum em questões de interpretação e reescrita.","dispositivo":null,"tags":["semântica"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Semântica: sentido e emprego dos vocábulos e campos semânticos"]]},{"termo":"Parônimos","extenso":"Palavras parônimas","pratica":"Palavras parecidas na escrita e no som, mas com sentidos diferentes: descrição e discrição, eminente e iminente.","tecnica":"Troca entre parônimos é erro de seleção vocabular, critério da redação no edital.","dispositivo":null,"tags":["semântica","redação"],"materias":["Língua Portuguesa","Redação (prova discursiva)"],"topicos":[["Língua Portuguesa","Semântica: sentido e emprego dos vocábulos e campos semânticos"],["Redação (prova discursiva)","Seleção vocabular e norma culta"]]},{"termo":"Homônimos","extenso":"Palavras homônimas","pratica":"Palavras com o mesmo som ou a mesma escrita e sentidos diferentes: sessão, seção e cessão.","tecnica":"Homófonas (mesmo som), homógrafas (mesma grafia) e perfeitas (som e grafia iguais).","dispositivo":null,"tags":["semântica"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Semântica: sentido e emprego dos vocábulos e campos semânticos"],["Língua Portuguesa","Ortografia"]]},{"termo":"Polissemia","extenso":"Polissemia","pratica":"É uma mesma palavra ter vários sentidos: \"pena\" de ave e \"pena\" de prisão.","tecnica":"Multiplicidade de sentidos de um vocábulo, definida pelo contexto.","dispositivo":null,"tags":["semântica"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Semântica: sentido e emprego dos vocábulos e campos semânticos"]]},{"termo":"Crase","extenso":"Sinal indicativo de crase","pratica":"É a fusão de \"a\" preposição com \"a\" artigo, marcada pelo acento grave: vou à secretaria.","tecnica":"Ocorre antes de palavra feminina que aceita artigo, regida por termo que exige \"a\". Proibida antes de masculino, de verbo e da maioria dos pronomes de tratamento. Obrigatória em locuções femininas (às vezes, à medida que).","dispositivo":null,"tags":["gramática"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Emprego do sinal indicativo de crase"]]},{"termo":"Próclise","extenso":"Pronome antes do verbo","pratica":"É o pronome antes do verbo: \"Não me disseram\".","tecnica":"Obrigatória com palavras atrativas: negação, pronomes relativos e indefinidos, conjunções subordinativas e advérbios sem pausa.","dispositivo":null,"tags":["colocação pronominal"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Colocação pronominal"]]},{"termo":"Mesóclise","extenso":"Pronome no meio do verbo","pratica":"É o pronome no meio do verbo: \"far-se-á\".","tecnica":"Só com futuro do presente ou do pretérito e quando não há palavra atrativa que exija próclise.","dispositivo":null,"tags":["colocação pronominal"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Colocação pronominal"]]},{"termo":"Ênclise","extenso":"Pronome depois do verbo","pratica":"É o pronome depois do verbo: \"Entregaram-me o processo\".","tecnica":"Regra para início de frase: a norma culta não começa oração com pronome oblíquo átono. Também com imperativo afirmativo e infinitivo.","dispositivo":null,"tags":["colocação pronominal"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Colocação pronominal"]]},{"termo":"Regência verbal","extenso":"Regência verbal","pratica":"É o verbo pedir ou não uma preposição: assistir \"ao\" filme, obedecer \"ao\" chefe.","tecnica":"Casos clássicos: assistir (ver) a; aspirar (desejar) a; visar (pretender) a; obedecer a; implicar (acarretar) é transitivo direto. Mudança de regência pode mudar o sentido.","dispositivo":null,"tags":["regência"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Transitividade e regência de nomes e verbos"]]},{"termo":"Regência nominal","extenso":"Regência nominal","pratica":"É o nome (substantivo ou adjetivo) pedir preposição: acessível \"a\", apto \"para\".","tecnica":"Relação de dependência entre um nome e seu complemento nominal, sempre preposicionado.","dispositivo":null,"tags":["regência"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Transitividade e regência de nomes e verbos"]]},{"termo":"VTD e VTI","extenso":"Verbo transitivo direto e verbo transitivo indireto","pratica":"VTD liga direto ao complemento (\"assinou o ofício\"). VTI precisa de preposição (\"gosta de prazos\").","tecnica":"VTD tem objeto direto; VTI tem objeto indireto; VTDI tem os dois; VI não exige complemento. Só VTD admite voz passiva analítica.","dispositivo":null,"tags":["regência","sintaxe"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Transitividade e regência de nomes e verbos"],["Língua Portuguesa","Termos da oração"]]},{"termo":"Concordância verbal","extenso":"Concordância verbal","pratica":"É o verbo combinar com o sujeito: \"Os servidores chegaram\".","tecnica":"Pegadinhas: \"haver\" no sentido de existir é impessoal (há muitos processos); \"fazer\" indicando tempo também (faz dois anos); sujeito depois do verbo continua mandando na concordância.","dispositivo":null,"tags":["concordância"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Concordância verbal e nominal"]]},{"termo":"Concordância nominal","extenso":"Concordância nominal","pratica":"É o adjetivo combinar com o substantivo: \"documentos anexos\".","tecnica":"Anexo, incluso, obrigado e quite concordam. \"Meio\" advérbio não varia (meio cansada). \"É proibido entrada\" sem artigo, mas \"é proibida a entrada\" com artigo.","dispositivo":null,"tags":["concordância"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Concordância verbal e nominal"]]},{"termo":"Oração coordenada","extenso":"Oração coordenada","pratica":"São orações independentes, ligadas lado a lado: \"Estudei e passei\".","tecnica":"Classificam-se em aditivas, adversativas, alternativas, conclusivas e explicativas.","dispositivo":null,"tags":["sintaxe"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Coordenação e subordinação"]]},{"termo":"Oração subordinada","extenso":"Oração subordinada","pratica":"É uma oração que depende de outra para fazer sentido: \"Passei porque estudei\".","tecnica":"Substantivas, adjetivas (restritivas ou explicativas) e adverbiais (causais, concessivas, condicionais, temporais etc.).","dispositivo":null,"tags":["sintaxe"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Coordenação e subordinação"]]},{"termo":"Conjunção adversativa","extenso":"Conjunção coordenativa adversativa","pratica":"Liga ideias contrárias: mas, porém, contudo, todavia, entretanto.","tecnica":"Introduz oposição. A banca troca por concessivas (embora) exigindo mudança no modo verbal e na estrutura.","dispositivo":null,"tags":["conectivos"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Coordenação e subordinação"],["Língua Portuguesa","Reescrita de frases: substituição, deslocamento e paralelismo"]]},{"termo":"Conjunção concessiva","extenso":"Conjunção subordinativa concessiva","pratica":"Admite um fato que não impede o outro: embora, ainda que, mesmo que, conquanto.","tecnica":"Exige, em regra, verbo no subjuntivo (\"embora estivesse cansada\"). Reescritas trocam adversativa por concessiva.","dispositivo":null,"tags":["conectivos"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Coordenação e subordinação"],["Língua Portuguesa","Reescrita de frases: substituição, deslocamento e paralelismo"],["Língua Portuguesa","Emprego de tempos e modos dos verbos"]]},{"termo":"Oração adjetiva restritiva","extenso":"Oração subordinada adjetiva restritiva","pratica":"Delimita: \"Os servidores que estudaram passaram\" (só os que estudaram).","tecnica":"Vem sem vírgulas. Colocar vírgulas muda o sentido para explicativa.","dispositivo":null,"tags":["sintaxe","pontuação"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Coordenação e subordinação"],["Língua Portuguesa","Pontuação"]]},{"termo":"Oração adjetiva explicativa","extenso":"Oração subordinada adjetiva explicativa","pratica":"Generaliza: \"Os servidores, que estudaram, passaram\" (todos estudaram).","tecnica":"Vem entre vírgulas. Retirar as vírgulas altera o sentido do período.","dispositivo":null,"tags":["sintaxe","pontuação"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Coordenação e subordinação"],["Língua Portuguesa","Pontuação"]]},{"termo":"Voz passiva sintética","extenso":"Voz passiva pronominal","pratica":"É a passiva com \"se\": \"Vendem-se salas\" (salas são vendidas).","tecnica":"Verbo transitivo direto + se. O verbo concorda com o sujeito paciente: vendem-se salas, aluga-se sala.","dispositivo":null,"tags":["vozes verbais","concordância"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Concordância verbal e nominal"],["Língua Portuguesa","Termos da oração"]]},{"termo":"Índice de indeterminação do sujeito","extenso":"Partícula \"se\" indeterminadora","pratica":"É o \"se\" que esconde quem faz a ação: \"Precisa-se de servidores\".","tecnica":"Aparece com verbo transitivo indireto ou intransitivo; o verbo fica no singular.","dispositivo":null,"tags":["sintaxe","concordância"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Termos da oração"],["Língua Portuguesa","Concordância verbal e nominal"]]},{"termo":"Oração sem sujeito","extenso":"Oração sem sujeito","pratica":"Frase em que ninguém faz a ação: \"Choveu\", \"Há prazos\".","tecnica":"Verbos impessoais: fenômenos da natureza, haver no sentido de existir e fazer ou ser indicando tempo. Ficam na 3ª pessoa do singular (exceto \"ser\").","dispositivo":null,"tags":["sintaxe"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Termos da oração"]]},{"termo":"Paralelismo","extenso":"Paralelismo sintático e semântico","pratica":"É manter o mesmo formato em partes que se correspondem: \"não só estudar, mas também revisar\".","tecnica":"Estruturas coordenadas devem ter a mesma forma gramatical. Quebra de paralelismo é erro comum em reescrita.","dispositivo":null,"tags":["reescrita"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Reescrita de frases: substituição, deslocamento e paralelismo"]]},{"termo":"Tipo textual","extenso":"Tipo textual","pratica":"É o modo de organizar o texto: narrar, descrever, argumentar, explicar ou instruir.","tecnica":"Narrativo, descritivo, dissertativo (expositivo e argumentativo) e injuntivo. Um gênero pode misturar tipos.","dispositivo":null,"tags":["texto"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Gênero do texto: literário e não literário, narrativo, descritivo e argumentativo"]]},{"termo":"Gênero textual","extenso":"Gênero textual","pratica":"É a forma concreta que o texto tem no dia a dia: notícia, crônica, ofício, editorial.","tecnica":"Definido pela função social, pelo suporte e pelo estilo. Distinguir de tipo textual.","dispositivo":null,"tags":["texto"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Gênero do texto: literário e não literário, narrativo, descritivo e argumentativo"]]},{"termo":"Norma-padrão","extenso":"Norma culta ou padrão","pratica":"É o português \"de prova\", o da gramática, usado em documentos oficiais.","tecnica":"Referência para correção gramatical. Na redação, problemas de construção frasal descontam 0,4 ponto cada (critério Norma culta).","dispositivo":null,"tags":["variação"],"materias":["Língua Portuguesa","Redação (prova discursiva)"],"topicos":[["Língua Portuguesa","Variação linguística: norma culta"],["Redação (prova discursiva)","Seleção vocabular e norma culta"]]},{"termo":"Variação linguística","extenso":"Variação linguística","pratica":"É o jeito de falar mudar conforme região, grupo social, situação e época.","tecnica":"Diatópica (regional), diastrática (social), diafásica (situacional) e diacrônica (histórica). A norma culta é uma das variedades.","dispositivo":null,"tags":["variação"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Variação linguística: norma culta"]]},{"termo":"Derivação","extenso":"Derivação (formação de palavras)","pratica":"É criar palavra a partir de outra, com prefixo ou sufixo: infeliz, felizmente.","tecnica":"Prefixal, sufixal, parassintética (entardecer), regressiva (o corte, de cortar) e imprópria (mudança de classe: o jantar).","dispositivo":null,"tags":["morfologia"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Processos de formação de palavras"]]},{"termo":"Composição","extenso":"Composição (formação de palavras)","pratica":"É juntar duas palavras: guarda-chuva, planalto.","tecnica":"Justaposição, sem perda de sons (guarda-chuva, passatempo); aglutinação, com perda (planalto, aguardente).","dispositivo":null,"tags":["morfologia"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Processos de formação de palavras"]]},{"termo":"Modos verbais","extenso":"Indicativo, subjuntivo e imperativo","pratica":"Indicativo é certeza (\"ele estuda\"), subjuntivo é hipótese (\"se ele estudasse\"), imperativo é ordem (\"estude\").","tecnica":"Correlação de tempos: \"se estudasse, passaria\"; \"se estudar, passará\". Cobrado em reescrita.","dispositivo":null,"tags":["verbos"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Emprego de tempos e modos dos verbos"],["Língua Portuguesa","Flexão dos nomes e dos verbos"]]},{"termo":"Acentuação: regras gerais","extenso":"Oxítonas, paroxítonas e proparoxítonas","pratica":"Toda proparoxítona tem acento (público). Oxítonas com a, e, o, em levam acento (café, também).","tecnica":"Paroxítonas acentuadas terminam em l, n, r, x, ps, ã(s), ão(s), i(s), us, um, uns e ditongo. Após o Acordo, não há acento em ditongos abertos de paroxítonas (ideia, assembleia).","dispositivo":null,"tags":["acentuação"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Acentuação gráfica"]]},{"termo":"Classes gramaticais","extenso":"As 10 classes de palavras","pratica":"São os grupos de palavras: substantivo, adjetivo, verbo, advérbio, pronome, artigo, numeral, preposição, conjunção e interjeição.","tecnica":"A mesma palavra muda de classe conforme o uso (\"o jantar\" é substantivo). A banca cobra o sentido e o emprego no texto.","dispositivo":null,"tags":["morfologia"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Classes gramaticais: reconhecimento, emprego e sentido"]]},{"termo":"Dissertativo-argumentativo","extenso":"Texto dissertativo-argumentativo","pratica":"É o texto que defende uma opinião com argumentos, em introdução, desenvolvimento e conclusão.","tecnica":"Gênero exigido na redação do Técnico em 2022: de 15 a 20 linhas. Cada linha abaixo do mínimo tira 0,5 ponto; cada linha acima do máximo, 0,2.","dispositivo":null,"tags":["redação"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Gênero dissertativo-argumentativo (15 a 20 linhas)"]]},{"termo":"Tese","extenso":"Tese (redação)","pratica":"É a sua opinião principal sobre o tema, aquilo que o texto vai provar.","tecnica":"Deve aparecer clara na introdução e ser sustentada por argumentos nos parágrafos de desenvolvimento.","dispositivo":null,"tags":["redação"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Tema, tese e abordagem"]]},{"termo":"Abordagem do tema","extenso":"Critério Abordagem do tema","pratica":"É responder exatamente ao que o tema pede, com os argumentos mais importantes.","tecnica":"Vale 12 pontos no edital de 2022: capacidade de selecionar argumentos convenientes dentro do perfil esperado.","dispositivo":null,"tags":["redação"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Tema, tese e abordagem"],["Redação (prova discursiva)","Critérios de correção e penalidades do edital"]]},{"termo":"Progressão textual","extenso":"Critério Progressão textual","pratica":"É o texto avançar, com parágrafos bem ligados e sem repetir a mesma ideia.","tecnica":"Vale 12 pontos no edital de 2022: coesão e coerência entre parágrafos e evolução adequada das partes.","dispositivo":null,"tags":["redação"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Progressão textual: coesão e coerência entre parágrafos"],["Redação (prova discursiva)","Critérios de correção e penalidades do edital"]]},{"termo":"Fuga ao tema","extenso":"Fuga ao tema","pratica":"É escrever sobre outro assunto. Zera a redação.","tecnica":"Edital de 2022: fuga ao tema, ausência de texto, erro de preenchimento ou identificação em local indevido levam à nota zero.","dispositivo":null,"tags":["redação"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Critérios de correção e penalidades do edital"]]},{"termo":"Seleção vocabular","extenso":"Critério Seleção vocabular","pratica":"É escolher a palavra certa: sem gíria, sem marca de fala e sem trocar parônimos.","tecnica":"Vale 2 pontos, com desconto de 0,2 por erro: inadequação vocabular, parônimos, palavras gerais no lugar de específicas, marcas de oralidade.","dispositivo":null,"tags":["redação"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Seleção vocabular e norma culta"],["Redação (prova discursiva)","Critérios de correção e penalidades do edital"]]},{"termo":"Ética","extenso":"Ética","pratica":"É refletir sobre o que é certo ou errado e por quê, buscando razões que valham para todos.","tecnica":"Parte da filosofia que estuda os fundamentos da moral. Tende ao universal e ao teórico.","dispositivo":null,"tags":["ética"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Ética e moral"],["Ética no Serviço Público","Ética, princípios e valores"]]},{"termo":"Moral","extenso":"Moral","pratica":"São as regras de comportamento de um grupo, aprendidas no dia a dia.","tecnica":"Conjunto de normas e costumes de uma sociedade em determinada época. É prática e varia com a cultura.","dispositivo":null,"tags":["ética"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Ética e moral"]]},{"termo":"Valores","extenso":"Valores éticos","pratica":"É o que uma pessoa ou instituição considera importante: honestidade, justiça, respeito.","tecnica":"Orientam escolhas e se concretizam em princípios de conduta no serviço público (legalidade, impessoalidade, moralidade).","dispositivo":null,"tags":["ética"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Ética, princípios e valores"]]},{"termo":"Cidadania","extenso":"Cidadania","pratica":"É participar da vida pública: votar, cobrar o governo, cumprir deveres e exercer direitos.","tecnica":"Fundamento da República (CF, art. 1º, II). Ligada à democracia e ao controle social da administração.","dispositivo":null,"tags":["ética","constitucional"],"materias":["Ética no Serviço Público","Noções de Direito Constitucional"],"topicos":[["Ética no Serviço Público","Ética e democracia: exercício da cidadania"],["Noções de Direito Constitucional","Princípios fundamentais"],["Noções de Direito Constitucional","Cidadania, direitos políticos e partidos políticos"]]},{"termo":"Deveres do servidor","extenso":"Deveres do servidor (Lei 8.112, art. 116)","pratica":"São as obrigações de quem trabalha no serviço público: zelo, lealdade, atender bem, cumprir ordens legais.","tecnica":"Entre outros: exercer com zelo, ser leal, cumprir ordens superiores (exceto as manifestamente ilegais), atender com presteza, guardar sigilo e representar contra ilegalidade.","dispositivo":"Lei 8.112/1990, art. 116","tags":["Lei 8.112","disciplinar"],"materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: deveres e proibições"],["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Proibições do servidor","extenso":"Proibições ao servidor (Lei 8.112, art. 117)","pratica":"É o que o servidor não pode fazer: sair do trabalho sem autorização, usar o cargo em benefício próprio, receber propina.","tecnica":"Rol do art. 117. Violar os incisos I a VIII e XIX leva a advertência; IX a XVI, a demissão; XVII e XVIII, a suspensão.","dispositivo":"Lei 8.112/1990, art. 117","tags":["Lei 8.112","disciplinar"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: deveres e proibições"],["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"]]},{"termo":"Advertência","extenso":"Penalidade de advertência","pratica":"É a punição mais leve, por escrito.","tecnica":"Aplicada por escrito nas violações do art. 117, I a VIII e XIX, e de deveres sem gravidade (art. 129). O registro é cancelado após 3 anos sem nova infração (art. 131).","dispositivo":"Lei 8.112/1990, arts. 129 e 131","tags":["Lei 8.112","penalidades"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: responsabilidades e penalidades"],["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"]]},{"termo":"Suspensão","extenso":"Penalidade de suspensão","pratica":"É ficar afastado sem receber, por até 90 dias.","tecnica":"Reincidência em faltas punidas com advertência e demais casos sem demissão; até 90 dias (art. 130). Pode virar multa de 50% por dia, com o servidor trabalhando (§ 2º). Registro cancelado após 5 anos.","dispositivo":"Lei 8.112/1990, art. 130","tags":["Lei 8.112","penalidades"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: responsabilidades e penalidades"],["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"]]},{"termo":"Demissão","extenso":"Penalidade de demissão","pratica":"É perder o cargo como punição por falta grave.","tecnica":"Hipóteses do art. 132: crime contra a administração, abandono de cargo, inassiduidade habitual, improbidade, corrupção, entre outras. Exige PAD.","dispositivo":"Lei 8.112/1990, art. 132","tags":["Lei 8.112","penalidades"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: responsabilidades e penalidades"],["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"]]},{"termo":"Cassação de aposentadoria","extenso":"Cassação de aposentadoria ou disponibilidade","pratica":"É tirar a aposentadoria de quem cometeu, na ativa, falta punível com demissão.","tecnica":"Art. 134: aplicada ao inativo que houver praticado, na atividade, falta punível com demissão.","dispositivo":"Lei 8.112/1990, art. 134","tags":["Lei 8.112","penalidades"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: responsabilidades e penalidades"]]},{"termo":"Destituição de cargo em comissão","extenso":"Destituição de cargo em comissão","pratica":"É a \"demissão\" de quem ocupa só cargo em comissão.","tecnica":"Art. 135: aplicada ao não ocupante de cargo efetivo nas infrações sujeitas a suspensão e demissão.","dispositivo":"Lei 8.112/1990, art. 135","tags":["Lei 8.112","penalidades"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: responsabilidades e penalidades"]]},{"termo":"Abandono de cargo","extenso":"Abandono de cargo","pratica":"É faltar de propósito por mais de 30 dias seguidos.","tecnica":"Ausência intencional do servidor ao serviço por mais de 30 dias consecutivos (art. 138). Leva à demissão.","dispositivo":"Lei 8.112/1990, art. 138","tags":["Lei 8.112","penalidades"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: responsabilidades e penalidades"]]},{"termo":"Inassiduidade habitual","extenso":"Inassiduidade habitual","pratica":"É faltar sem justificativa 60 dias, mesmo que não seguidos, dentro de 12 meses.","tecnica":"Falta ao serviço sem causa justificada por 60 dias, interpoladamente, durante o período de 12 meses (art. 139). Leva à demissão.","dispositivo":"Lei 8.112/1990, art. 139","tags":["Lei 8.112","penalidades"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: responsabilidades e penalidades"]]},{"termo":"Acumulação de cargos","extenso":"Acumulação remunerada de cargos públicos","pratica":"Em regra, não pode ter dois cargos públicos pagos ao mesmo tempo, salvo algumas exceções.","tecnica":"Permitida, com compatibilidade de horários, para dois cargos de professor, um de professor com outro técnico ou científico, e dois de profissionais de saúde regulamentados (CF, art. 37, XVI). Lei 8.112, arts. 118 a 120.","dispositivo":"CF, art. 37, XVI; Lei 8.112/1990, art. 118","tags":["Lei 8.112"],"materias":["Ética no Serviço Público","Noções de Direito Constitucional"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: acumulação de cargos"],["Noções de Direito Constitucional","Servidores públicos"]]},{"termo":"Responsabilidade civil, penal e administrativa","extenso":"Independência das instâncias","pratica":"O mesmo erro do servidor pode gerar três processos diferentes: um de indenização, um criminal e um disciplinar.","tecnica":"As sanções são cumuláveis e independentes (art. 125). A absolvição criminal que negue a existência do fato ou a autoria afasta a responsabilidade administrativa (art. 126).","dispositivo":"Lei 8.112/1990, arts. 121 a 126","tags":["Lei 8.112"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: responsabilidades e penalidades"]]},{"termo":"Prescrição disciplinar","extenso":"Prescrição da ação disciplinar","pratica":"É o prazo que a administração tem para punir o servidor.","tecnica":"5 anos para demissão, cassação e destituição; 2 anos para suspensão; 180 dias para advertência. Conta da data em que o fato se tornou conhecido (art. 142).","dispositivo":"Lei 8.112/1990, art. 142","tags":["Lei 8.112","prazos"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"]]},{"termo":"LIA","extenso":"Lei de Improbidade Administrativa (Lei 8.429/1992)","pratica":"É a lei que pune o agente público desonesto que enriquece ilicitamente, causa prejuízo ou viola princípios.","tecnica":"Muito alterada pela Lei 14.230/2021: todos os atos de improbidade exigem dolo. Três espécies: enriquecimento ilícito (art. 9º), lesão ao erário (art. 10) e violação de princípios (art. 11).","dispositivo":"Lei 8.429/1992","tags":["improbidade"],"materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Lei 8.429/1992 (improbidade): disposições gerais"],["Noções de Direito Administrativo","Improbidade administrativa"]]},{"termo":"Enriquecimento ilícito","extenso":"Improbidade por enriquecimento ilícito","pratica":"É o agente ganhar dinheiro ou bens indevidos por causa do cargo.","tecnica":"Art. 9º: auferir, mediante ato doloso, vantagem patrimonial indevida em razão do cargo, mandato, função ou emprego.","dispositivo":"Lei 8.429/1992, art. 9º","tags":["improbidade"],"materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Lei 8.429/1992: atos de improbidade administrativa"],["Noções de Direito Administrativo","Improbidade administrativa"]]},{"termo":"Lesão ao erário","extenso":"Improbidade que causa lesão ao erário","pratica":"É causar prejuízo aos cofres públicos.","tecnica":"Art. 10: ação ou omissão dolosa que cause perda patrimonial efetiva. Desde a Lei 14.230/2021 não existe mais modalidade culposa.","dispositivo":"Lei 8.429/1992, art. 10","tags":["improbidade"],"materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Lei 8.429/1992: atos de improbidade administrativa"],["Noções de Direito Administrativo","Improbidade administrativa"]]},{"termo":"Improbidade contra princípios","extenso":"Improbidade que atenta contra os princípios da administração","pratica":"É violar a honestidade e a imparcialidade mesmo sem enriquecer nem causar prejuízo.","tecnica":"Art. 11: condutas dolosas listadas na lei. Após a Lei 14.230/2021, o rol passou a ser taxativo.","dispositivo":"Lei 8.429/1992, art. 11","tags":["improbidade"],"materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Lei 8.429/1992: atos de improbidade administrativa"],["Noções de Direito Administrativo","Improbidade administrativa"]]},{"termo":"Código de Ética do TJDFT","extenso":"Código de Ética dos Servidores do TJDFT","pratica":"São as regras de conduta próprias de quem trabalha no TJDFT.","tecnica":"Resolução TJDFT nº 9/2019, complementada pela Portaria Conjunta nº 76/2020. Leia a íntegra: o edital cobra o texto das normas.","dispositivo":"Resolução TJDFT 9/2019; Portaria Conjunta 76/2020","tags":["ética","TJDFT"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Código de Ética dos Servidores do TJDFT (Resolução 9/2019 e Portaria Conjunta 76/2020)"]]},{"termo":"RITJDFT","extenso":"Regimento Interno do TJDFT","pratica":"É o \"manual de funcionamento\" do Tribunal: quem julga o quê e como.","tecnica":"Portaria GPR 354/2016, republicada no DJe de 30/03/2016, com as Emendas Regimentais posteriores. O edital cobra o Regimento inteiro.","dispositivo":"Portaria GPR 354/2016","tags":["TJDFT","regimento"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Disposições iniciais e composição do Tribunal"],["Regimento Interno do TJDFT","Emendas Regimentais posteriores a 2016"]]},{"termo":"Desembargador","extenso":"Desembargador","pratica":"É o juiz de segunda instância, que integra o Tribunal.","tecnica":"Membro do Tribunal de Justiça; julga em órgãos colegiados (turmas, câmaras, conselhos e pleno).","dispositivo":null,"tags":["TJDFT","regimento"],"materias":["Regimento Interno do TJDFT","Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Regimento Interno do TJDFT","Disposições iniciais e composição do Tribunal"],["Lei de Organização Judiciária do DF e dos Territórios","Tribunal de Justiça: composição e competência"]]},{"termo":"Tribunal Pleno","extenso":"Tribunal Pleno","pratica":"É a reunião de todos os desembargadores do Tribunal.","tecnica":"Órgão máximo do Tribunal; suas atribuições estão no Regimento Interno.","dispositivo":null,"tags":["TJDFT","regimento"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Tribunal Pleno, Conselho Especial e Conselho da Magistratura"]]},{"termo":"Conselho Especial","extenso":"Conselho Especial do TJDFT","pratica":"É o órgão do TJDFT que reúne parte dos desembargadores para decidir as questões mais importantes.","tecnica":"Exerce, no TJDFT, atribuições que a Constituição admite delegar a órgão especial (CF, art. 93, XI). Confira no Regimento a composição e as competências.","dispositivo":null,"tags":["TJDFT","regimento"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Tribunal Pleno, Conselho Especial e Conselho da Magistratura"]]},{"termo":"Conselho da Magistratura","extenso":"Conselho da Magistratura","pratica":"É o órgão que cuida de questões administrativas e disciplinares ligadas aos juízes.","tecnica":"Composição e competências definidas no Regimento Interno. Não confundir com o CNJ, que é órgão nacional.","dispositivo":null,"tags":["TJDFT","regimento"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Tribunal Pleno, Conselho Especial e Conselho da Magistratura"]]},{"termo":"Corregedoria da Justiça","extenso":"Corregedoria da Justiça do DF e dos Territórios","pratica":"É quem fiscaliza e orienta os juízes e os cartórios de primeira instância.","tecnica":"Exercida pelo Corregedor; edita provimentos, como o Provimento Geral da Corregedoria, que também é cobrado no edital.","dispositivo":null,"tags":["TJDFT","regimento"],"materias":["Regimento Interno do TJDFT","Provimento Geral da Corregedoria"],"topicos":[["Regimento Interno do TJDFT","Presidência, Vice-Presidências e Corregedoria"],["Provimento Geral da Corregedoria","Provimento Geral da Corregedoria aplicado aos Juízes e Ofícios Judiciais (2014) e alterações"]]},{"termo":"Relator","extenso":"Desembargador relator","pratica":"É o desembargador responsável por estudar o processo e levar o voto ao colegiado.","tecnica":"Definido pela distribuição; conduz o processo no tribunal e decide monocraticamente nos casos previstos em lei e no Regimento.","dispositivo":null,"tags":["regimento"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Registro, distribuição e prevenção"],["Regimento Interno do TJDFT","Sessões, pauta e julgamento"]]},{"termo":"Prevenção","extenso":"Prevenção (distribuição)","pratica":"É o mesmo relator ou órgão continuar com processos ligados ao primeiro que recebeu.","tecnica":"Critério de distribuição por dependência que torna o julgador \"prevento\" para feitos conexos ou relacionados. Regras no Regimento.","dispositivo":null,"tags":["regimento","distribuição"],"materias":["Regimento Interno do TJDFT","Noções de Direito Processual Civil"],"topicos":[["Regimento Interno do TJDFT","Registro, distribuição e prevenção"],["Noções de Direito Processual Civil","Competência: disposições gerais, modificação e incompetência"]]},{"termo":"Acórdão","extenso":"Acórdão","pratica":"É a decisão tomada por um grupo de desembargadores.","tecnica":"Julgamento colegiado proferido pelos tribunais (CPC, art. 204).","dispositivo":"CPC, art. 204","tags":["regimento","processo"],"materias":["Regimento Interno do TJDFT","Noções de Direito Processual Civil"],"topicos":[["Regimento Interno do TJDFT","Sessões, pauta e julgamento"],["Noções de Direito Processual Civil","Atos judiciais: despachos, decisões interlocutórias e sentenças"]]},{"termo":"Quinto constitucional","extenso":"Quinto constitucional","pratica":"É a regra que reserva parte das vagas dos tribunais para advogados e membros do Ministério Público.","tecnica":"Um quinto dos lugares dos TRFs e dos TJs, para membros do MP e advogados com mais de 10 anos de carreira ou atividade, em lista sêxtupla e depois tríplice (CF, art. 94).","dispositivo":"CF, art. 94","tags":["Judiciário"],"materias":["Noções de Direito Constitucional","Regimento Interno do TJDFT"],"topicos":[["Noções de Direito Constitucional","Órgãos do Poder Judiciário e competências"],["Regimento Interno do TJDFT","Disposições iniciais e composição do Tribunal"]]},{"termo":"LOJDFT","extenso":"Lei de Organização Judiciária do DF e dos Territórios (Lei 11.697/2008)","pratica":"É a lei que organiza a Justiça do DF: tribunal, varas, circunscrições e juízes.","tecnica":"Lei federal, porque a Justiça do DF é organizada e mantida pela União (CF, art. 21, XIII, e art. 22, XVII).","dispositivo":"Lei 11.697/2008","tags":["TJDFT","LOJ"],"materias":["Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Lei 11.697/2008: disposições gerais e composição da Justiça do DF"]]},{"termo":"Circunscrição judiciária","extenso":"Circunscrição judiciária","pratica":"É a \"região\" da Justiça no DF, como Brasília, Taguatinga ou Ceilândia, cada uma com suas varas.","tecnica":"Divisão territorial da Justiça do DF para fins de competência e administração. A lista e as varas de cada uma estão na Lei 11.697/2008 e alterações.","dispositivo":null,"tags":["TJDFT","LOJ"],"materias":["Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Circunscrições judiciárias e Varas"]]},{"termo":"Vara","extenso":"Vara judicial","pratica":"É a unidade da primeira instância onde o juiz trabalha, com seu cartório.","tecnica":"Órgão de primeiro grau com competência definida por matéria e território (cível, família, criminal, Fazenda Pública etc.).","dispositivo":null,"tags":["TJDFT","LOJ"],"materias":["Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Circunscrições judiciárias e Varas"],["Lei de Organização Judiciária do DF e dos Territórios","Competência das Varas"]]},{"termo":"Juiz de Direito Substituto","extenso":"Juiz de Direito Substituto","pratica":"É o juiz que começa a carreira e atua onde for designado, substituindo ou auxiliando.","tecnica":"Cargo inicial da magistratura do DF; o titular de vara é o Juiz de Direito. Regras na Lei 11.697/2008.","dispositivo":null,"tags":["TJDFT","LOJ"],"materias":["Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Juízes de Direito e Juízes de Direito Substitutos"]]},{"termo":"Juizado Especial","extenso":"Juizados Especiais Cíveis e Criminais","pratica":"São os juizados para causas mais simples, mais rápidos e com menos formalidade.","tecnica":"Lei 9.099/1995: cíveis para causas de menor complexidade (até 40 salários mínimos) e criminais para infrações de menor potencial ofensivo. Organização no DF pela Lei 11.697/2008.","dispositivo":"Lei 9.099/1995","tags":["TJDFT","LOJ"],"materias":["Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Juizados Especiais"]]},{"termo":"PGC","extenso":"Provimento Geral da Corregedoria aplicado aos Juízes e Ofícios Judiciais","pratica":"É o manual da Corregedoria que diz como juízes e cartórios devem trabalhar no dia a dia.","tecnica":"Disponibilizado no DJe de 10/10/2014 e alterações. Também caem os Provimentos nº 07/2010 e nº 03/2011.","dispositivo":null,"tags":["Corregedoria"],"materias":["Provimento Geral da Corregedoria"],"topicos":[["Provimento Geral da Corregedoria","Provimento Geral da Corregedoria aplicado aos Juízes e Ofícios Judiciais (2014) e alterações"]]},{"termo":"Ofício judicial","extenso":"Ofício judicial (secretaria da vara)","pratica":"É o cartório da vara, onde os servidores movimentam os processos.","tecnica":"Unidade que dá cumprimento aos atos processuais e às determinações do juiz, nos termos do PGC.","dispositivo":null,"tags":["Corregedoria","cartório"],"materias":["Provimento Geral da Corregedoria"],"topicos":[["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"]]},{"termo":"Autuação","extenso":"Autuação","pratica":"É \"abrir\" o processo: registrar e montar os autos com a primeira peça.","tecnica":"Ato de cartório que forma os autos e registra os dados do processo.","dispositivo":null,"tags":["cartório"],"materias":["Provimento Geral da Corregedoria"],"topicos":[["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"]]},{"termo":"Juntada","extenso":"Juntada","pratica":"É anexar um documento ou petição aos autos do processo.","tecnica":"Ato ordinatório praticado pelo servidor; no processo eletrônico, a juntada é automática ao protocolar.","dispositivo":null,"tags":["cartório"],"materias":["Provimento Geral da Corregedoria","Provimento Judicial aplicado ao PJe"],"topicos":[["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"],["Provimento Judicial aplicado ao PJe","Peticionamento, intimações e prazos no PJe"]]},{"termo":"Certidão","extenso":"Certidão cartorária","pratica":"É o servidor atestar oficialmente um fato do processo, por exemplo que o prazo terminou.","tecnica":"Documento com fé pública lavrado pelo ofício judicial.","dispositivo":null,"tags":["cartório"],"materias":["Provimento Geral da Corregedoria"],"topicos":[["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"]]},{"termo":"Conclusos","extenso":"Autos conclusos","pratica":"É mandar o processo para o juiz decidir ou despachar.","tecnica":"A conclusão é o ato que encaminha os autos ao magistrado; os prazos do juiz contam a partir dela.","dispositivo":null,"tags":["cartório"],"materias":["Provimento Geral da Corregedoria"],"topicos":[["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"]]},{"termo":"Ato ordinatório","extenso":"Ato meramente ordinatório","pratica":"É um ato de andamento que o próprio servidor faz, sem precisar do juiz, como juntar uma petição ou abrir vista.","tecnica":"Praticado de ofício pelo servidor e revisto pelo juiz quando necessário (CPC, art. 203, § 4º).","dispositivo":"CPC, art. 203, § 4º","tags":["cartório","processo"],"materias":["Provimento Geral da Corregedoria","Noções de Direito Processual Civil"],"topicos":[["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"],["Noções de Direito Processual Civil","Atos judiciais: despachos, decisões interlocutórias e sentenças"]]},{"termo":"PJe","extenso":"Processo Judicial Eletrônico","pratica":"É o sistema onde os processos tramitam pela internet, sem papel.","tecnica":"Lei 11.419/2006 e, no TJDFT, o Provimento Judicial aplicado ao PJe (DJe de 21/08/2017 e alterações).","dispositivo":"Lei 11.419/2006","tags":["PJe"],"materias":["Provimento Judicial aplicado ao PJe","Noções de Direito Processual Civil"],"topicos":[["Provimento Judicial aplicado ao PJe","Provimento Judicial aplicado ao Processo Judicial Eletrônico (2017) e alterações"],["Noções de Direito Processual Civil","Processo judicial eletrônico: Lei 11.419/2006"]]},{"termo":"DJe","extenso":"Diário da Justiça eletrônico","pratica":"É o jornal oficial da Justiça na internet, onde saem as publicações.","tecnica":"Considera-se publicação o primeiro dia útil seguinte ao da disponibilização; os prazos começam no primeiro dia útil seguinte à publicação (Lei 11.419/2006, art. 4º, §§ 3º e 4º).","dispositivo":"Lei 11.419/2006, art. 4º","tags":["PJe","prazos"],"materias":["Provimento Judicial aplicado ao PJe","Noções de Direito Processual Civil"],"topicos":[["Provimento Judicial aplicado ao PJe","Peticionamento, intimações e prazos no PJe"],["Noções de Direito Processual Civil","Processo judicial eletrônico: Lei 11.419/2006"],["Noções de Direito Processual Civil","Comunicação dos atos processuais"]]},{"termo":"Intimação eletrônica","extenso":"Intimação por meio eletrônico","pratica":"É a intimação feita no sistema. Ela vale quando você abre, ou depois de 10 dias se não abrir.","tecnica":"Considera-se feita no dia da consulta ao teor; se a consulta não ocorrer em 10 dias corridos do envio, considera-se feita ao fim desse prazo (Lei 11.419/2006, art. 5º).","dispositivo":"Lei 11.419/2006, art. 5º","tags":["PJe","prazos"],"materias":["Provimento Judicial aplicado ao PJe","Noções de Direito Processual Civil"],"topicos":[["Provimento Judicial aplicado ao PJe","Peticionamento, intimações e prazos no PJe"],["Noções de Direito Processual Civil","Processo judicial eletrônico: Lei 11.419/2006"],["Noções de Direito Processual Civil","Comunicação dos atos processuais"]]},{"termo":"Prazo no processo eletrônico","extenso":"Tempestividade do peticionamento eletrônico","pratica":"No sistema, dá para protocolar até 23h59 do último dia do prazo.","tecnica":"Consideram-se tempestivas as petições transmitidas até as 24 horas do último dia do prazo (Lei 11.419/2006, art. 3º, parágrafo único).","dispositivo":"Lei 11.419/2006, art. 3º","tags":["PJe","prazos"],"materias":["Provimento Judicial aplicado ao PJe","Noções de Direito Processual Civil"],"topicos":[["Provimento Judicial aplicado ao PJe","Peticionamento, intimações e prazos no PJe"],["Noções de Direito Processual Civil","Processo judicial eletrônico: Lei 11.419/2006"]]},{"termo":"Assinatura eletrônica","extenso":"Assinatura eletrônica no processo","pratica":"É a \"assinatura\" digital que identifica quem enviou a peça no sistema.","tecnica":"Lei 11.419/2006, art. 1º, § 2º, III: assinatura digital com certificado de autoridade certificadora credenciada ou cadastro do usuário no Poder Judiciário.","dispositivo":"Lei 11.419/2006, art. 1º","tags":["PJe"],"materias":["Provimento Judicial aplicado ao PJe","Noções de Direito Processual Civil"],"topicos":[["Provimento Judicial aplicado ao PJe","Peticionamento, intimações e prazos no PJe"],["Noções de Direito Processual Civil","Processo judicial eletrônico: Lei 11.419/2006"]]},{"termo":"Gestão por competências","extenso":"Gestão por competências","pratica":"É organizar a gestão de pessoas pelo que cada um sabe, sabe fazer e como se comporta no trabalho.","tecnica":"Mapeia as competências necessárias à estratégia, identifica lacunas (gap) e orienta seleção, treinamento e avaliação.","dispositivo":null,"tags":["gestão de pessoas"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Gestão por competências"],["Noções de Administração de Recursos Humanos e Gestão Pública","Gestão estratégica de pessoas"]]},{"termo":"CHA","extenso":"Conhecimentos, Habilidades e Atitudes","pratica":"Conhecimento é o saber, habilidade é o saber fazer, atitude é o querer fazer.","tecnica":"Dimensões da competência individual na literatura de gestão por competências.","dispositivo":null,"tags":["gestão de pessoas"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Gestão por competências"]]},{"termo":"T&D","extenso":"Treinamento e Desenvolvimento","pratica":"Treinamento prepara para o cargo atual; desenvolvimento prepara a pessoa para o futuro.","tecnica":"Etapas do treinamento: diagnóstico (levantamento de necessidades), planejamento, execução e avaliação dos resultados.","dispositivo":null,"tags":["gestão de pessoas"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Treinamento e desenvolvimento"]]},{"termo":"Avaliação 360 graus","extenso":"Avaliação 360°","pratica":"É ser avaliado por todos ao redor: chefe, colegas, subordinados e às vezes o público.","tecnica":"Método de avaliação de desempenho com múltiplas fontes; reduz o viés de um único avaliador.","dispositivo":null,"tags":["avaliação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Avaliação do desempenho humano"]]},{"termo":"Efeito halo","extenso":"Efeito halo (erro de avaliação)","pratica":"É deixar uma característica marcante contaminar a nota de todo o resto.","tecnica":"Erro de avaliação de desempenho em que uma impressão geral, boa ou ruim, influencia todos os critérios. Outros: tendência central, leniência, recência.","dispositivo":null,"tags":["avaliação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Avaliação do desempenho humano"]]},{"termo":"Descrição de cargo","extenso":"Descrição de cargo","pratica":"É dizer O QUE o cargo faz: tarefas e responsabilidades.","tecnica":"Aspectos intrínsecos do cargo (conteúdo). Diferente da análise, que trata dos requisitos do ocupante.","dispositivo":null,"tags":["cargos"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Modelagem do trabalho: descrição, análise e desenho de cargos"]]},{"termo":"Análise de cargo","extenso":"Análise de cargo","pratica":"É dizer O QUE É PRECISO para ocupar o cargo: formação, experiência, esforço, condições de trabalho.","tecnica":"Aspectos extrínsecos: requisitos intelectuais, físicos, responsabilidades e condições de trabalho. Métodos de coleta: entrevista, questionário, observação.","dispositivo":null,"tags":["cargos"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Modelagem do trabalho: descrição, análise e desenho de cargos"]]},{"termo":"Pirâmide de Maslow","extenso":"Hierarquia das necessidades de Maslow","pratica":"As pessoas buscam primeiro o básico (comer, segurança) e depois reconhecimento e realização.","tecnica":"Fisiológicas, segurança, sociais, estima e autorrealização. Uma necessidade satisfeita deixa de motivar.","dispositivo":null,"tags":["motivação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Motivação"]]},{"termo":"Teoria dos dois fatores","extenso":"Teoria de Herzberg","pratica":"Salário e ambiente bons evitam a insatisfação, mas o que motiva de verdade é o trabalho em si.","tecnica":"Fatores higiênicos (extrínsecos: salário, condições, supervisão) evitam insatisfação; fatores motivacionais (intrínsecos: reconhecimento, responsabilidade, crescimento) geram satisfação.","dispositivo":null,"tags":["motivação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Motivação"]]},{"termo":"Missão","extenso":"Missão organizacional","pratica":"É a razão de existir da organização, o que ela faz hoje e para quem.","tecnica":"Declaração do propósito e do negócio da organização. Orienta a estratégia junto com visão e valores.","dispositivo":null,"tags":["estratégia"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Missão, visão de futuro e valores"]]},{"termo":"Visão de futuro","extenso":"Visão","pratica":"É onde a organização quer chegar daqui a alguns anos.","tecnica":"Estado futuro desejado, inspirador e com horizonte de tempo.","dispositivo":null,"tags":["estratégia"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Missão, visão de futuro e valores"]]},{"termo":"Valores organizacionais","extenso":"Valores organizacionais","pratica":"São as crenças que guiam o comportamento de todos na organização: transparência, ética, eficiência.","tecnica":"Princípios que orientam decisões e condutas e sustentam missão e visão.","dispositivo":null,"tags":["estratégia"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Missão, visão de futuro e valores"]]},{"termo":"Análise SWOT","extenso":"Strengths, Weaknesses, Opportunities, Threats (FOFA)","pratica":"É listar forças e fraquezas de dentro, e oportunidades e ameaças de fora.","tecnica":"Forças e fraquezas são do ambiente interno (controláveis); oportunidades e ameaças, do externo.","dispositivo":null,"tags":["estratégia"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Análise dos ambientes interno e externo"],["Noções de Administração de Recursos Humanos e Gestão Pública","Mudança e inovação organizacional"]]},{"termo":"Administração patrimonialista","extenso":"Modelo patrimonialista","pratica":"É quando o governante trata o que é público como se fosse dele.","tecnica":"Confusão entre público e privado, nepotismo, clientelismo e corrupção como traços do modelo.","dispositivo":null,"tags":["gestão pública"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Modelos de gestão pública: patrimonialista, burocrático e gerencial"]]},{"termo":"Administração burocrática","extenso":"Modelo burocrático (Weber)","pratica":"É a administração das regras, da hierarquia e do concurso público, para combater o \"jeitinho\".","tecnica":"Impessoalidade, formalismo, hierarquia e profissionalização. Disfunções: rigidez, apego às normas, foco no processo e não no resultado.","dispositivo":null,"tags":["gestão pública"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Modelos de gestão pública: patrimonialista, burocrático e gerencial"]]},{"termo":"Administração gerencial","extenso":"Modelo gerencial (nova gestão pública)","pratica":"É administrar com foco em resultado e no cidadão, como uma organização eficiente.","tecnica":"Controle por resultados, descentralização, flexibilidade e cidadão como cliente. No Brasil, marcado pelo Plano Diretor da Reforma do Aparelho do Estado (1995).","dispositivo":null,"tags":["gestão pública"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Modelos de gestão pública: patrimonialista, burocrático e gerencial"]]},{"termo":"Eficiência","extenso":"Eficiência","pratica":"É fazer bem feito gastando pouco.","tecnica":"Relação entre recursos usados e produtos entregues: \"fazer certo as coisas\". Também é princípio do art. 37 da CF.","dispositivo":null,"tags":["desempenho"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de Direito Administrativo"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Eficácia e efetividade: avaliação e mensuração do desempenho governamental"],["Noções de Direito Administrativo","Princípios expressos e implícitos da administração pública"]]},{"termo":"Eficácia","extenso":"Eficácia","pratica":"É atingir a meta combinada.","tecnica":"Grau de alcance dos objetivos e metas: \"fazer as coisas certas\".","dispositivo":null,"tags":["desempenho"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Eficácia e efetividade: avaliação e mensuração do desempenho governamental"]]},{"termo":"Efetividade","extenso":"Efetividade","pratica":"É a ação mudar de verdade a vida das pessoas.","tecnica":"Impacto e transformação gerados na sociedade pela política pública.","dispositivo":null,"tags":["desempenho"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Eficácia e efetividade: avaliação e mensuração do desempenho governamental"]]},{"termo":"Princípio da anualidade","extenso":"Princípio orçamentário da anualidade","pratica":"O orçamento vale por um ano.","tecnica":"O orçamento vigora por um exercício financeiro, que coincide com o ano civil (Lei 4.320/1964, arts. 2º e 34).","dispositivo":"Lei 4.320/1964, art. 34","tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Orçamento público: princípios orçamentários"]]},{"termo":"Princípio da unidade","extenso":"Princípio orçamentário da unidade","pratica":"Cada governo tem um único orçamento.","tecnica":"Um só orçamento para cada ente da Federação em cada exercício.","dispositivo":null,"tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Orçamento público: princípios orçamentários"]]},{"termo":"Princípio da universalidade","extenso":"Princípio orçamentário da universalidade","pratica":"Todas as receitas e todas as despesas entram no orçamento.","tecnica":"A LOA deve conter todas as receitas e despesas (Lei 4.320/1964, arts. 2º e 3º).","dispositivo":null,"tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Orçamento público: princípios orçamentários"]]},{"termo":"Princípio da exclusividade","extenso":"Princípio orçamentário da exclusividade","pratica":"A lei do orçamento só trata de receita e despesa.","tecnica":"A LOA não conterá dispositivo estranho à previsão da receita e à fixação da despesa, salvo autorização para créditos suplementares e operações de crédito (CF, art. 165, § 8º).","dispositivo":"CF, art. 165, § 8º","tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Orçamento público: princípios orçamentários"]]},{"termo":"Empenho","extenso":"Empenho da despesa","pratica":"É reservar o dinheiro do orçamento para um gasto, antes de pagar.","tecnica":"Ato da autoridade que cria para o Estado obrigação de pagamento (Lei 4.320, art. 58). É vedada despesa sem prévio empenho (art. 60).","dispositivo":"Lei 4.320/1964, arts. 58 a 61","tags":["orçamento","despesa"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Receita e despesa públicas: conceito, classificação e estágios"]]},{"termo":"Liquidação","extenso":"Liquidação da despesa","pratica":"É conferir se o serviço foi prestado ou o produto entregue antes de pagar.","tecnica":"Verificação do direito adquirido pelo credor, com base nos documentos comprobatórios (Lei 4.320, art. 63).","dispositivo":"Lei 4.320/1964, art. 63","tags":["orçamento","despesa"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Receita e despesa públicas: conceito, classificação e estágios"]]},{"termo":"Pagamento","extenso":"Pagamento da despesa","pratica":"É a entrega do dinheiro ao credor, depois da liquidação.","tecnica":"Só após a regular liquidação (Lei 4.320, art. 62), por ordem de pagamento (art. 64).","dispositivo":"Lei 4.320/1964, arts. 62 e 64","tags":["orçamento","despesa"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Receita e despesa públicas: conceito, classificação e estágios"]]},{"termo":"Estágios da receita","extenso":"Previsão, lançamento, arrecadação e recolhimento","pratica":"É o caminho do dinheiro que entra: prever, cobrar, receber e depositar no caixa do governo.","tecnica":"Previsão (planejamento), lançamento, arrecadação e recolhimento à conta única, conforme o MCASP.","dispositivo":null,"tags":["orçamento","receita"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Receita e despesa públicas: conceito, classificação e estágios"],["Noções de Administração de Recursos Humanos e Gestão Pública","MCASP 9ª ed., Parte I: procedimentos contábeis orçamentários"]]},{"termo":"Restos a pagar","extenso":"Restos a pagar","pratica":"São despesas empenhadas que ficaram sem pagar no fim do ano.","tecnica":"Despesas empenhadas e não pagas até 31 de dezembro (Lei 4.320, art. 36). Processados: já liquidados; não processados: ainda não liquidados.","dispositivo":"Lei 4.320/1964, art. 36","tags":["orçamento","despesa"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Suprimento de fundos, restos a pagar e despesas de exercícios anteriores"]]},{"termo":"Suprimento de fundos","extenso":"Suprimento de fundos (regime de adiantamento)","pratica":"É um dinheiro adiantado a um servidor para pequenas despesas que não podem esperar o processo normal.","tecnica":"Entrega de numerário a servidor, sempre precedida de empenho, para despesas que não possam subordinar-se ao processo normal de aplicação (Lei 4.320, arts. 65 e 68).","dispositivo":"Lei 4.320/1964, art. 68","tags":["orçamento","despesa"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Suprimento de fundos, restos a pagar e despesas de exercícios anteriores"]]},{"termo":"DEA","extenso":"Despesas de exercícios anteriores","pratica":"É pagar hoje uma conta de um ano que já fechou.","tecnica":"Despesas de exercícios encerrados com dotação suficiente que não se processaram na época, restos a pagar com prescrição interrompida e compromissos reconhecidos depois (Lei 4.320, art. 37).","dispositivo":"Lei 4.320/1964, art. 37","tags":["orçamento","despesa"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Suprimento de fundos, restos a pagar e despesas de exercícios anteriores"]]},{"termo":"Crédito suplementar","extenso":"Crédito adicional suplementar","pratica":"É reforçar uma despesa que já está no orçamento mas ficou curta.","tecnica":"Destinado a reforço de dotação orçamentária (Lei 4.320, art. 41, I). Autorizado por lei e aberto por decreto, com indicação de recursos.","dispositivo":"Lei 4.320/1964, arts. 41 a 43","tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Diretrizes orçamentárias, processo orçamentário e emendas ao orçamento"]]},{"termo":"Crédito especial","extenso":"Crédito adicional especial","pratica":"É criar uma despesa nova que não estava prevista no orçamento.","tecnica":"Para despesas sem dotação específica (Lei 4.320, art. 41, II). Autorizado por lei e aberto por decreto.","dispositivo":"Lei 4.320/1964, art. 41","tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Diretrizes orçamentárias, processo orçamentário e emendas ao orçamento"]]},{"termo":"Crédito extraordinário","extenso":"Crédito adicional extraordinário","pratica":"É dinheiro para emergência: guerra, comoção interna ou calamidade.","tecnica":"Despesas imprevisíveis e urgentes (CF, art. 167, § 3º). Na União, aberto por medida provisória.","dispositivo":"CF, art. 167, § 3º","tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Diretrizes orçamentárias, processo orçamentário e emendas ao orçamento"]]},{"termo":"Emendas ao orçamento","extenso":"Emendas ao projeto de lei orçamentária","pratica":"São as mudanças que os parlamentares fazem no orçamento proposto pelo Executivo.","tecnica":"Devem ser compatíveis com o PPA e a LDO e indicar os recursos, admitidos apenas os de anulação de despesa, vedadas as que incidam sobre pessoal, serviço da dívida e transferências constitucionais (CF, art. 166, § 3º).","dispositivo":"CF, art. 166, § 3º","tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Diretrizes orçamentárias, processo orçamentário e emendas ao orçamento"]]},{"termo":"MCASP","extenso":"Manual de Contabilidade Aplicada ao Setor Público","pratica":"É o manual oficial de como registrar receitas e despesas públicas.","tecnica":"O edital de 2022 cobrou a 9ª edição, Parte I (Procedimentos Contábeis Orçamentários), aprovada pela Portaria Conjunta STN/SOF/ME nº 117/2021.","dispositivo":null,"tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","MCASP 9ª ed., Parte I: procedimentos contábeis orçamentários"]]},{"termo":"Cláusula pétrea","extenso":"Cláusula pétrea","pratica":"É o núcleo da Constituição que não pode ser abolido nem por emenda.","tecnica":"Não será objeto de deliberação a proposta de emenda tendente a abolir: a forma federativa; o voto direto, secreto, universal e periódico; a separação dos Poderes; os direitos e garantias individuais (CF, art. 60, § 4º).","dispositivo":"CF, art. 60, § 4º","tags":["constitucional"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Constituição: conceito e classificações"]]},{"termo":"Constituição rígida","extenso":"Constituição rígida","pratica":"É a Constituição que exige um processo mais difícil para ser mudada do que uma lei comum.","tecnica":"A CF/88 é rígida: emenda exige 3/5 dos votos, em dois turnos, em cada Casa do Congresso (art. 60, § 2º). Também é escrita, promulgada, dogmática e analítica.","dispositivo":"CF, art. 60, § 2º","tags":["constitucional"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Constituição: conceito e classificações"]]},{"termo":"Fundamentos da República","extenso":"Fundamentos da República Federativa do Brasil","pratica":"São as bases do país: soberania, cidadania, dignidade da pessoa humana, trabalho e livre iniciativa, pluralismo político.","tecnica":"CF, art. 1º. Mnemônico: SO-CI-DI-VA-PLU. Não confundir com objetivos (art. 3º), que são verbos de ação.","dispositivo":"CF, art. 1º","tags":["constitucional"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Princípios fundamentais"]]},{"termo":"Objetivos fundamentais","extenso":"Objetivos fundamentais da República","pratica":"São as metas do país: sociedade livre, justa e solidária, desenvolvimento, fim da pobreza e da discriminação.","tecnica":"CF, art. 3º: construir, garantir, erradicar e reduzir, promover o bem de todos. Começam com verbos.","dispositivo":"CF, art. 3º","tags":["constitucional"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Princípios fundamentais"]]},{"termo":"Brasileiro nato","extenso":"Brasileiro nato","pratica":"É quem nasceu brasileiro, aqui ou em certos casos lá fora.","tecnica":"Hipóteses do art. 12, I. Cargos privativos de nato: Presidente e Vice, Presidentes da Câmara e do Senado, Ministro do STF, carreira diplomática, oficial das Forças Armadas e Ministro de Estado da Defesa (art. 12, § 3º).","dispositivo":"CF, art. 12","tags":["nacionalidade"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Nacionalidade"]]},{"termo":"Brasileiro naturalizado","extenso":"Brasileiro naturalizado","pratica":"É o estrangeiro que se tornou brasileiro.","tecnica":"Art. 12, II. Pode ser extraditado por crime comum praticado antes da naturalização ou por tráfico de drogas (art. 5º, LI). O nato nunca é extraditado.","dispositivo":"CF, arts. 5º, LI, e 12, II","tags":["nacionalidade"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Nacionalidade"]]},{"termo":"Alistamento eleitoral e voto","extenso":"Obrigatoriedade do alistamento e do voto","pratica":"Votar é obrigatório dos 18 aos 70 anos; é opcional para quem tem 16 ou 17, mais de 70 ou é analfabeto.","tecnica":"CF, art. 14, § 1º. Estrangeiros e conscritos (durante o serviço militar obrigatório) não podem se alistar (§ 2º).","dispositivo":"CF, art. 14","tags":["direitos políticos"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Cidadania, direitos políticos e partidos políticos"]]},{"termo":"Inelegibilidade","extenso":"Inelegibilidade","pratica":"É não poder se candidatar.","tecnica":"São inelegíveis os inalistáveis e os analfabetos (CF, art. 14, § 4º), além de outras hipóteses constitucionais e da LC 64/1990.","dispositivo":"CF, art. 14, §§ 4º a 9º","tags":["direitos políticos"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Cidadania, direitos políticos e partidos políticos"]]},{"termo":"Partido político","extenso":"Partido político","pratica":"É a associação de pessoas para disputar eleições e defender ideias.","tecnica":"Pessoa jurídica de direito privado, com autonomia; registra o estatuto no TSE (CF, art. 17).","dispositivo":"CF, art. 17","tags":["direitos políticos"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Cidadania, direitos políticos e partidos políticos"]]},{"termo":"Autonomia federativa","extenso":"Autonomia dos entes federados","pratica":"Cada ente (União, Estados, DF, Municípios) cuida de si, dentro das regras da Constituição.","tecnica":"Capacidade de auto-organização, autogoverno, autoadministração e autolegislação (CF, art. 18). Soberania é só da República.","dispositivo":"CF, art. 18","tags":["federação"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Organização político-administrativa: União, Estados, DF, Municípios e Territórios"]]},{"termo":"Territórios federais","extenso":"Territórios federais","pratica":"São áreas administradas pela União, sem a autonomia de um Estado. Hoje não existe nenhum.","tecnica":"Integram a União; criação, transformação em Estado ou reintegração dependem de lei complementar (CF, art. 18, § 2º). A Justiça dos Territórios também está a cargo da União.","dispositivo":"CF, arts. 18, § 2º, e 33","tags":["federação"],"materias":["Noções de Direito Constitucional","Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Noções de Direito Constitucional","Organização político-administrativa: União, Estados, DF, Municípios e Territórios"],["Lei de Organização Judiciária do DF e dos Territórios","Lei 11.697/2008: disposições gerais e composição da Justiça do DF"]]},{"termo":"Competência privativa","extenso":"Competência legislativa privativa da União","pratica":"São os assuntos sobre os quais só a União faz lei, como direito civil, penal e processual.","tecnica":"CF, art. 22. Pode ser delegada aos Estados por lei complementar em questões específicas (parágrafo único).","dispositivo":"CF, art. 22","tags":["federação"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Organização político-administrativa: União, Estados, DF, Municípios e Territórios"]]},{"termo":"Competência comum","extenso":"Competência administrativa comum","pratica":"São tarefas que todos os entes fazem juntos, como cuidar da saúde e do meio ambiente.","tecnica":"CF, art. 23: competência material de União, Estados, DF e Municípios.","dispositivo":"CF, art. 23","tags":["federação"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Organização político-administrativa: União, Estados, DF, Municípios e Territórios"]]},{"termo":"Competência concorrente","extenso":"Competência legislativa concorrente","pratica":"São assuntos em que a União faz as regras gerais e os Estados completam.","tecnica":"CF, art. 24: União edita normas gerais; Estados e DF suplementam. Sem lei federal, o Estado exerce competência plena até a superveniência dela.","dispositivo":"CF, art. 24","tags":["federação"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Organização político-administrativa: União, Estados, DF, Municípios e Territórios"]]},{"termo":"LIMPE","extenso":"Legalidade, Impessoalidade, Moralidade, Publicidade e Eficiência","pratica":"São os cinco princípios que toda a administração pública deve seguir.","tecnica":"Princípios expressos do art. 37, caput, da CF. Implícitos: supremacia e indisponibilidade do interesse público, razoabilidade, proporcionalidade, autotutela, entre outros.","dispositivo":"CF, art. 37","tags":["princípios"],"materias":["Noções de Direito Constitucional","Noções de Direito Administrativo"],"topicos":[["Noções de Direito Constitucional","Administração pública: disposições gerais"],["Noções de Direito Administrativo","Princípios expressos e implícitos da administração pública"]]},{"termo":"Concurso público","extenso":"Concurso público","pratica":"É a seleção obrigatória para cargo efetivo e emprego público.","tecnica":"CF, art. 37, II. Validade de até 2 anos, prorrogável uma vez por igual período (III). Cargos em comissão são de livre nomeação.","dispositivo":"CF, art. 37, II a IV","tags":["servidores"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Administração pública: disposições gerais"],["Noções de Direito Constitucional","Servidores públicos"]]},{"termo":"Teto remuneratório","extenso":"Teto remuneratório do serviço público","pratica":"Nenhum servidor pode ganhar mais que um ministro do STF.","tecnica":"O subsídio mensal dos Ministros do STF é o limite geral (CF, art. 37, XI), com subtetos nos Estados e Municípios.","dispositivo":"CF, art. 37, XI","tags":["servidores"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Servidores públicos"]]},{"termo":"Garantias da magistratura","extenso":"Vitaliciedade, inamovibilidade e irredutibilidade de subsídio","pratica":"São proteções dos juízes para decidirem com independência.","tecnica":"CF, art. 95. Vitaliciedade após 2 anos de exercício no primeiro grau; perda do cargo só por sentença judicial transitada em julgado.","dispositivo":"CF, art. 95","tags":["Judiciário"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Poder Judiciário: disposições gerais"]]},{"termo":"Súmula vinculante","extenso":"Súmula vinculante","pratica":"É um entendimento do STF que todos os juízes e a administração são obrigados a seguir.","tecnica":"Aprovada pelo STF por 2/3 dos membros, após reiteradas decisões sobre matéria constitucional (CF, art. 103-A). Descumprimento cabe reclamação.","dispositivo":"CF, art. 103-A","tags":["Judiciário"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Órgãos do Poder Judiciário e competências"]]},{"termo":"Repercussão geral","extenso":"Repercussão geral no recurso extraordinário","pratica":"É o filtro do STF: só julga recurso extraordinário sobre questões importantes para muita gente.","tecnica":"O recorrente deve demonstrá-la; o STF só pode recusá-la pela manifestação de 2/3 dos membros (CF, art. 102, § 3º).","dispositivo":"CF, art. 102, § 3º","tags":["Judiciário","recursos"],"materias":["Noções de Direito Constitucional","Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Constitucional","Órgãos do Poder Judiciário e competências"],["Noções de Direito Processual Civil","Recursos para o STF e para o STJ"]]},{"termo":"MPDFT","extenso":"Ministério Público do Distrito Federal e Territórios","pratica":"É o Ministério Público que atua na Justiça do DF, junto ao TJDFT.","tecnica":"Integra o Ministério Público da União (CF, art. 128, I, d), embora atue na Justiça comum do DF.","dispositivo":"CF, art. 128, I, d","tags":["funções essenciais"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Funções essenciais à Justiça: Ministério Público"]]},{"termo":"Administração direta","extenso":"Administração pública direta","pratica":"É o próprio governo agindo por seus órgãos: ministérios, secretarias.","tecnica":"Conjunto de órgãos integrados às pessoas políticas (União, Estados, DF, Municípios). Fruto de desconcentração.","dispositivo":null,"tags":["organização"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Organização administrativa: administração direta e indireta"]]},{"termo":"Administração indireta","extenso":"Administração pública indireta","pratica":"São entidades criadas pelo governo, com personalidade própria: autarquias, fundações, empresas estatais.","tecnica":"Autarquias, fundações públicas, empresas públicas e sociedades de economia mista (DL 200/1967, art. 4º). Fruto de descentralização.","dispositivo":null,"tags":["organização"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Organização administrativa: administração direta e indireta"]]},{"termo":"Autarquia","extenso":"Autarquia","pratica":"É uma entidade pública criada por lei para fazer um serviço típico de Estado, como o INSS.","tecnica":"Pessoa jurídica de direito público, criada por lei específica (CF, art. 37, XIX), com patrimônio e receita próprios.","dispositivo":"CF, art. 37, XIX","tags":["organização"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Organização administrativa: administração direta e indireta"]]},{"termo":"Empresa pública","extenso":"Empresa pública","pratica":"É uma empresa 100% do governo, como a Caixa.","tecnica":"Pessoa jurídica de direito privado, criação autorizada por lei, capital integralmente público, qualquer forma societária (Lei 13.303/2016).","dispositivo":null,"tags":["organização"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Organização administrativa: administração direta e indireta"]]},{"termo":"Sociedade de economia mista","extenso":"Sociedade de economia mista","pratica":"É uma empresa do governo com sócios privados, como o Banco do Brasil.","tecnica":"Pessoa jurídica de direito privado, criação autorizada por lei, sob a forma de sociedade anônima, com maioria das ações com direito a voto do ente público.","dispositivo":null,"tags":["organização"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Organização administrativa: administração direta e indireta"]]},{"termo":"Desconcentração","extenso":"Desconcentração administrativa","pratica":"É dividir tarefas dentro do mesmo órgão ou pessoa, criando setores. Há chefe e subordinado.","tecnica":"Distribuição interna de competências na mesma pessoa jurídica, com hierarquia.","dispositivo":null,"tags":["organização"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Centralização, descentralização e desconcentração"]]},{"termo":"Descentralização","extenso":"Descentralização administrativa","pratica":"É passar a tarefa para outra pessoa jurídica, como uma autarquia ou uma concessionária.","tecnica":"Transferência para outra pessoa, por outorga (lei, transfere a titularidade) ou delegação (contrato ou ato, transfere a execução). Não há hierarquia, há controle (tutela).","dispositivo":null,"tags":["organização"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Centralização, descentralização e desconcentração"]]},{"termo":"Teoria do órgão","extenso":"Teoria do órgão (imputação)","pratica":"Quando o servidor age, é o Estado que está agindo.","tecnica":"A atuação do agente é imputada à pessoa jurídica a que pertence. Órgãos não têm personalidade jurídica.","dispositivo":null,"tags":["organização"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Órgãos públicos"]]},{"termo":"Autotutela","extenso":"Princípio da autotutela","pratica":"A administração pode corrigir os próprios atos sem precisar ir à Justiça.","tecnica":"Pode anular os atos ilegais e revogar os inconvenientes ou inoportunos, respeitados os direitos adquiridos (Súmula 473 do STF; Lei 9.784, art. 53).","dispositivo":"Súmula 473 STF; Lei 9.784/1999, art. 53","tags":["princípios"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Princípios expressos e implícitos da administração pública"],["Noções de Direito Administrativo","Ato administrativo"]]},{"termo":"Poder de polícia","extenso":"Poder de polícia","pratica":"É o poder de limitar a liberdade individual em favor da coletividade: fiscalizar, multar, interditar.","tecnica":"Conceito legal no CTN, art. 78. Atributos: discricionariedade (em regra), autoexecutoriedade e coercibilidade. Ciclo: ordem, consentimento, fiscalização e sanção.","dispositivo":"CTN, art. 78","tags":["poderes"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Poderes administrativos"]]},{"termo":"Poder hierárquico","extenso":"Poder hierárquico","pratica":"É o poder do chefe de dar ordens, rever e coordenar o trabalho dos subordinados.","tecnica":"Permite ordenar, coordenar, controlar, delegar e avocar competências, nos limites da lei.","dispositivo":null,"tags":["poderes"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Poderes administrativos"]]},{"termo":"Poder disciplinar","extenso":"Poder disciplinar","pratica":"É o poder de punir servidores (e quem tem vínculo especial com a administração).","tecnica":"Apuração de infrações e aplicação de penalidades a quem está sujeito à disciplina administrativa, com contraditório e ampla defesa.","dispositivo":null,"tags":["poderes"],"materias":["Noções de Direito Administrativo","Ética no Serviço Público"],"topicos":[["Noções de Direito Administrativo","Poderes administrativos"],["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"]]},{"termo":"Poder regulamentar","extenso":"Poder regulamentar (normativo)","pratica":"É o poder do chefe do Executivo de detalhar como uma lei será cumprida.","tecnica":"Edição de decretos e regulamentos para fiel execução da lei (CF, art. 84, IV); não pode inovar na ordem jurídica, salvo o decreto autônomo do art. 84, VI.","dispositivo":"CF, art. 84, IV e VI","tags":["poderes"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Poderes administrativos"]]},{"termo":"Excesso de poder","extenso":"Abuso de poder: excesso","pratica":"É o agente ir além do que tem competência para fazer.","tecnica":"Vício de competência: atua fora dos limites das suas atribuições.","dispositivo":null,"tags":["poderes"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Poderes administrativos"],["Noções de Direito Administrativo","Ato administrativo"]]},{"termo":"Desvio de finalidade","extenso":"Abuso de poder: desvio de finalidade","pratica":"É usar a competência que tem para um objetivo diferente do previsto, como perseguir alguém.","tecnica":"Vício de finalidade: ato praticado visando fim diverso do previsto, explícita ou implicitamente, na regra de competência.","dispositivo":null,"tags":["poderes"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Poderes administrativos"],["Noções de Direito Administrativo","Ato administrativo"]]},{"termo":"Elementos do ato administrativo","extenso":"Competência, finalidade, forma, motivo e objeto","pratica":"São as cinco partes de todo ato: quem pode, para quê, como, por quê e o quê.","tecnica":"Mnemônico COM-FI-FOR-M-OB. Competência, finalidade e forma são vinculados; motivo e objeto podem ser discricionários.","dispositivo":null,"tags":["ato administrativo"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Ato administrativo"]]},{"termo":"Atributos do ato administrativo","extenso":"Presunção de legitimidade, autoexecutoriedade, tipicidade e imperatividade","pratica":"São as \"forças\" do ato: presume-se correto, pode ser executado direto e se impõe a todos.","tecnica":"Mnemônico PATI. Nem todo ato tem autoexecutoriedade e imperatividade; a presunção de legitimidade é relativa.","dispositivo":null,"tags":["ato administrativo"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Ato administrativo"]]},{"termo":"Anulação","extenso":"Anulação do ato administrativo","pratica":"É desfazer um ato porque ele é ilegal.","tecnica":"Por ilegalidade, pela administração ou pelo Judiciário, com efeitos retroativos (ex tunc). Prazo de 5 anos para anular atos favoráveis, salvo má-fé (Lei 9.784, art. 54).","dispositivo":"Lei 9.784/1999, arts. 53 e 54","tags":["ato administrativo"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Ato administrativo"],["Noções de Direito Administrativo","Processo administrativo: Lei 9.784/1999"]]},{"termo":"Revogação","extenso":"Revogação do ato administrativo","pratica":"É desfazer um ato válido porque deixou de ser conveniente.","tecnica":"Por conveniência e oportunidade, só pela própria administração, com efeitos dali em diante (ex nunc). Não alcança atos vinculados nem os que geraram direito adquirido.","dispositivo":null,"tags":["ato administrativo"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Ato administrativo"]]},{"termo":"Convalidação","extenso":"Convalidação","pratica":"É consertar um ato com defeito pequeno, sem precisar anular.","tecnica":"Atos com defeitos sanáveis, que não lesem o interesse público nem terceiros, podem ser convalidados (Lei 9.784, art. 55). Vícios de competência (não exclusiva) e forma (não essencial) são sanáveis.","dispositivo":"Lei 9.784/1999, art. 55","tags":["ato administrativo"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Ato administrativo"]]},{"termo":"Teoria dos motivos determinantes","extenso":"Teoria dos motivos determinantes","pratica":"Se a administração dá um motivo para o ato, fica presa a ele. Motivo falso anula o ato.","tecnica":"A validade do ato se vincula aos motivos declarados; se forem inexistentes ou falsos, o ato é nulo.","dispositivo":null,"tags":["ato administrativo"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Ato administrativo"]]},{"termo":"Responsabilidade objetiva do Estado","extenso":"Teoria do risco administrativo","pratica":"O Estado indeniza o dano causado por seus agentes, mesmo sem culpa. Basta provar o dano e a ligação com a ação.","tecnica":"CF, art. 37, § 6º: pessoas de direito público e de direito privado prestadoras de serviço público respondem objetivamente; excludentes: culpa exclusiva da vítima, caso fortuito e força maior.","dispositivo":"CF, art. 37, § 6º","tags":["responsabilidade civil"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Responsabilidade civil do Estado"]]},{"termo":"Ação regressiva","extenso":"Direito de regresso contra o agente","pratica":"Depois de pagar a indenização, o Estado cobra do servidor que agiu com dolo ou culpa.","tecnica":"Responsabilidade subjetiva do agente perante o Estado (CF, art. 37, § 6º, parte final; Lei 8.112, art. 122, § 2º).","dispositivo":"CF, art. 37, § 6º","tags":["responsabilidade civil"],"materias":["Noções de Direito Administrativo","Ética no Serviço Público"],"topicos":[["Noções de Direito Administrativo","Responsabilidade civil do Estado"],["Ética no Serviço Público","Lei 8.112/1990: responsabilidades e penalidades"]]},{"termo":"TCU e TCDF","extenso":"Tribunal de Contas da União e Tribunal de Contas do DF","pratica":"São os órgãos que ajudam o Legislativo a fiscalizar como o dinheiro público é gasto.","tecnica":"Auxiliam o controle externo (CF, art. 71). Julgam contas de administradores, apreciam a legalidade de admissões e aposentadorias e aplicam sanções.","dispositivo":"CF, arts. 70 a 75","tags":["controle"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Controle pelos Tribunais de Contas"]]},{"termo":"Modalidades de licitação (Lei 14.133)","extenso":"Pregão, concorrência, concurso, leilão e diálogo competitivo","pratica":"São os cinco \"tipos\" de licitação da lei nova.","tecnica":"Art. 28 da Lei 14.133/2021. Tomada de preços e convite deixaram de existir.","dispositivo":"Lei 14.133/2021, art. 28","tags":["licitação"],"materias":["Noções de Direito Administrativo","Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"],["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de licitação: fases, modalidades, dispensa e inexigibilidade"]]},{"termo":"Pregão","extenso":"Pregão","pratica":"É a licitação para comprar bens e serviços comuns, com lances, como um leilão ao contrário.","tecnica":"Para bens e serviços comuns; critério de julgamento menor preço ou maior desconto (Lei 14.133, art. 6º, XLI). Antes regulado pela Lei 10.520/2002.","dispositivo":"Lei 14.133/2021; Lei 10.520/2002","tags":["licitação"],"materias":["Noções de Direito Administrativo","Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"],["Noções de Direito Administrativo","Licitações e contratos: Leis 8.666/1993 e 10.520/2002"],["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de licitação: fases, modalidades, dispensa e inexigibilidade"]]},{"termo":"Diálogo competitivo","extenso":"Diálogo competitivo","pratica":"É a licitação em que o governo conversa com as empresas para descobrir a melhor solução antes da proposta final.","tecnica":"Para contratações de inovação tecnológica ou soluções que exigem adaptação, com diálogos com licitantes pré-selecionados (Lei 14.133, art. 32).","dispositivo":"Lei 14.133/2021, art. 32","tags":["licitação"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"]]},{"termo":"Dispensa de licitação","extenso":"Licitação dispensável","pratica":"Dá para licitar, mas a lei permite não licitar, por exemplo em compras de pequeno valor ou emergências.","tecnica":"Hipóteses taxativas do art. 75 da Lei 14.133/2021. A competição é possível.","dispositivo":"Lei 14.133/2021, art. 75","tags":["licitação"],"materias":["Noções de Direito Administrativo","Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"],["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de licitação: fases, modalidades, dispensa e inexigibilidade"]]},{"termo":"Inexigibilidade de licitação","extenso":"Inexigibilidade de licitação","pratica":"Não tem como licitar porque não há competição: fornecedor exclusivo ou artista consagrado.","tecnica":"Inviabilidade de competição (Lei 14.133, art. 74), com rol exemplificativo: fornecedor exclusivo, artista consagrado, serviços técnicos especializados de natureza predominantemente intelectual com notória especialização.","dispositivo":"Lei 14.133/2021, art. 74","tags":["licitação"],"materias":["Noções de Direito Administrativo","Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"],["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de licitação: fases, modalidades, dispensa e inexigibilidade"]]},{"termo":"Cláusulas exorbitantes","extenso":"Cláusulas exorbitantes dos contratos administrativos","pratica":"São poderes especiais que o governo tem no contrato, como mudar ou encerrar o contrato sozinho.","tecnica":"Prerrogativas como alteração e extinção unilaterais, fiscalização, aplicação de sanções e ocupação provisória (Lei 14.133, art. 104).","dispositivo":"Lei 14.133/2021, art. 104","tags":["contratos"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"]]},{"termo":"Recurso administrativo (Lei 9.784)","extenso":"Recurso no processo administrativo federal","pratica":"É pedir que outra autoridade reveja a decisão, em 10 dias.","tecnica":"Prazo de 10 dias (art. 59); dirigido à autoridade que decidiu, que pode reconsiderar em 5 dias antes de encaminhar (art. 56, § 1º); no máximo 3 instâncias (art. 57).","dispositivo":"Lei 9.784/1999, arts. 56 a 59","tags":["processo administrativo","prazos"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Processo administrativo: Lei 9.784/1999"]]},{"termo":"Lei distrital 2.834/2001","extenso":"Processo administrativo no Distrito Federal","pratica":"É a lei que manda o DF usar as regras da Lei 9.784 nos seus processos administrativos.","tecnica":"Recepciona a Lei federal 9.784/1999 no âmbito da administração do Distrito Federal.","dispositivo":"Lei distrital 2.834/2001","tags":["processo administrativo"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Processo administrativo no DF: Lei distrital 2.834/2001"]]},{"termo":"Agente público","extenso":"Agente público","pratica":"É qualquer pessoa que exerce função pública, mesmo sem salário ou por pouco tempo.","tecnica":"Gênero que inclui agentes políticos, servidores (estatutários, empregados públicos e temporários), militares e particulares em colaboração (como mesários e jurados).","dispositivo":null,"tags":["agentes"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Agentes públicos"]]},{"termo":"Capacidade de direito","extenso":"Capacidade de direito (de gozo)","pratica":"Todo mundo que nasce com vida pode ter direitos.","tecnica":"Aptidão genérica para ser titular de direitos e deveres, ligada à personalidade (CC, art. 1º).","dispositivo":"CC, art. 1º","tags":["pessoas"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Pessoas naturais: personalidade e capacidade"]]},{"termo":"Capacidade de fato","extenso":"Capacidade de fato (de exercício)","pratica":"É poder exercer os direitos sozinho, sem precisar de representante.","tecnica":"Adquirida, em regra, aos 18 anos (CC, art. 5º). Incapazes são representados (absolutos) ou assistidos (relativos).","dispositivo":"CC, art. 5º","tags":["pessoas"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Pessoas naturais: personalidade e capacidade"]]},{"termo":"Absolutamente incapaz","extenso":"Absolutamente incapaz","pratica":"Hoje, só o menor de 16 anos.","tecnica":"CC, art. 3º, na redação dada pelo Estatuto da Pessoa com Deficiência (Lei 13.146/2015). Atos praticados sem representante são nulos.","dispositivo":"CC, art. 3º","tags":["pessoas"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Pessoas naturais: personalidade e capacidade"]]},{"termo":"Relativamente incapaz","extenso":"Relativamente incapaz","pratica":"Quem tem 16 ou 17 anos, ébrios habituais, viciados em tóxico, quem não pode exprimir vontade e os pródigos.","tecnica":"CC, art. 4º. Atos praticados sem assistência são anuláveis.","dispositivo":"CC, art. 4º","tags":["pessoas"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Pessoas naturais: personalidade e capacidade"]]},{"termo":"Emancipação","extenso":"Emancipação","pratica":"É o menor passar a ser capaz antes dos 18.","tecnica":"CC, art. 5º, parágrafo único: concessão dos pais (a partir de 16, por instrumento público), sentença judicial, casamento, emprego público efetivo, colação de grau superior, estabelecimento ou emprego com economia própria (a partir de 16).","dispositivo":"CC, art. 5º, parágrafo único","tags":["pessoas"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Pessoas naturais: personalidade e capacidade"]]},{"termo":"Nascituro","extenso":"Nascituro","pratica":"É o bebê já concebido que ainda não nasceu. A lei protege os direitos dele.","tecnica":"A personalidade civil começa do nascimento com vida, mas a lei põe a salvo, desde a concepção, os direitos do nascituro (CC, art. 2º).","dispositivo":"CC, art. 2º","tags":["pessoas"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Pessoas naturais: personalidade e capacidade"],["Noções de Direito Civil","Direitos da personalidade"]]},{"termo":"Comoriência","extenso":"Comoriência","pratica":"Quando duas pessoas morrem no mesmo evento e não dá para saber quem morreu primeiro, considera-se que morreram juntas.","tecnica":"Presunção de morte simultânea (CC, art. 8º), relevante para a herança.","dispositivo":"CC, art. 8º","tags":["pessoas"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Pessoas naturais: personalidade e capacidade"]]},{"termo":"Domicílio","extenso":"Domicílio da pessoa natural","pratica":"É o lugar onde a pessoa mora com intenção de ficar.","tecnica":"Residência com ânimo definitivo (CC, art. 70). Pode haver vários (art. 71). Domicílio necessário do servidor público: onde exerce permanentemente suas funções (art. 76).","dispositivo":"CC, arts. 70 a 78","tags":["pessoas"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Nome, estado e domicílio da pessoa natural"],["Noções de Direito Civil","Pessoas jurídicas: disposições gerais e domicílio"]]},{"termo":"Direitos da personalidade","extenso":"Direitos da personalidade","pratica":"São direitos ligados à própria pessoa: nome, imagem, honra, corpo, privacidade.","tecnica":"Intransmissíveis e irrenunciáveis; seu exercício não pode sofrer limitação voluntária, salvo exceções legais (CC, art. 11).","dispositivo":"CC, arts. 11 a 21","tags":["pessoas"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Direitos da personalidade"]]},{"termo":"Desconsideração da personalidade jurídica","extenso":"Desconsideração da personalidade jurídica","pratica":"É o juiz \"furar\" a empresa para cobrar dos sócios que abusaram dela.","tecnica":"Abuso caracterizado por desvio de finalidade ou confusão patrimonial (CC, art. 50). No processo, via incidente próprio (CPC, arts. 133 a 137).","dispositivo":"CC, art. 50; CPC, art. 133","tags":["pessoa jurídica"],"materias":["Noções de Direito Civil","Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Civil","Pessoas jurídicas: disposições gerais e domicílio"],["Noções de Direito Processual Civil","Intervenção de terceiros"]]},{"termo":"Associação","extenso":"Associação","pratica":"É um grupo de pessoas unidas para um fim sem lucro, como um clube.","tecnica":"União de pessoas que se organizam para fins não econômicos; não há direitos e obrigações recíprocos entre os associados (CC, art. 53).","dispositivo":"CC, art. 53","tags":["pessoa jurídica"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Associações e fundações"]]},{"termo":"Fundação","extenso":"Fundação privada","pratica":"É um patrimônio destinado a uma finalidade social, como cultura ou assistência.","tecnica":"Criada por escritura pública ou testamento, com dotação especial de bens livres, para fins como assistência social, cultura, educação, saúde e pesquisa (CC, art. 62). Fiscalizada pelo Ministério Público.","dispositivo":"CC, art. 62","tags":["pessoa jurídica"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Associações e fundações"]]},{"termo":"Bens públicos","extenso":"Bens públicos","pratica":"São os bens que pertencem ao governo: praças, prédios, terras.","tecnica":"De uso comum do povo, de uso especial e dominicais (CC, art. 99). Os dois primeiros são inalienáveis enquanto afetados; nenhum está sujeito a usucapião (art. 102).","dispositivo":"CC, arts. 98 a 103","tags":["bens"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Bens"]]},{"termo":"Bens fungíveis","extenso":"Bens fungíveis e infungíveis","pratica":"Fungível é o que dá para trocar por outro igual (dinheiro, arroz). Infungível é único (um quadro original).","tecnica":"Fungíveis são os móveis que podem ser substituídos por outros da mesma espécie, qualidade e quantidade (CC, art. 85).","dispositivo":"CC, art. 85","tags":["bens"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Bens"]]},{"termo":"Pertenças","extenso":"Pertenças","pratica":"São coisas que servem a outra sem fazer parte dela, como os móveis de uma casa.","tecnica":"Não constituindo partes integrantes, se destinam ao uso, serviço ou aformoseamento de outro bem (CC, art. 93). Em regra, não seguem o principal (art. 94).","dispositivo":"CC, arts. 93 e 94","tags":["bens"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Bens"]]},{"termo":"Defeitos do negócio jurídico","extenso":"Vícios do consentimento e vícios sociais","pratica":"São problemas que tornam o contrato anulável: engano, enganação, ameaça, aproveitamento.","tecnica":"Erro, dolo, coação, estado de perigo, lesão e fraude contra credores: anuláveis, prazo decadencial de 4 anos (CC, arts. 171 e 178). Simulação torna o negócio nulo (art. 167).","dispositivo":"CC, arts. 138 a 165, 171 e 178","tags":["negócio jurídico"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Fatos jurídicos e negócio jurídico"]]},{"termo":"Nulidade","extenso":"Negócio jurídico nulo","pratica":"É o negócio que nasce morto: não produz efeito e não pode ser confirmado.","tecnica":"Hipóteses do CC, art. 166 (agente absolutamente incapaz, objeto ilícito, forma não prescrita etc.). Pode ser alegada por qualquer interessado e pelo MP; não convalesce com o tempo (art. 169).","dispositivo":"CC, arts. 166 a 169","tags":["negócio jurídico"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Fatos jurídicos e negócio jurídico"]]},{"termo":"Anulabilidade","extenso":"Negócio jurídico anulável","pratica":"É o negócio com defeito que vale até alguém pedir a anulação.","tecnica":"Incapacidade relativa e vícios (CC, art. 171). Pode ser confirmado pelas partes (art. 172) e só os interessados podem alegar.","dispositivo":"CC, arts. 171 a 177","tags":["negócio jurídico"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Fatos jurídicos e negócio jurídico"]]},{"termo":"Ato ilícito","extenso":"Ato ilícito","pratica":"É causar dano a alguém por ação, omissão, negligência ou imprudência. Gera dever de indenizar.","tecnica":"CC, art. 186. Abuso de direito também é ato ilícito (art. 187). Não são ilícitos a legítima defesa, o exercício regular de direito e o estado de necessidade (art. 188).","dispositivo":"CC, arts. 186 a 188","tags":["responsabilidade"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Atos jurídicos lícitos e atos ilícitos"]]},{"termo":"Prescrição","extenso":"Prescrição (civil)","pratica":"É perder o direito de cobrar na Justiça por ter esperado demais.","tecnica":"Extingue a pretensão (CC, art. 189). Prazo geral de 10 anos (art. 205). Os prazos não podem ser alterados por acordo das partes (art. 192).","dispositivo":"CC, arts. 189 a 206","tags":["prazos"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Prescrição e decadência"]]},{"termo":"Decadência","extenso":"Decadência (civil)","pratica":"É perder o próprio direito por não exercê-lo no prazo.","tecnica":"Atinge direitos potestativos. A decadência legal não se suspende nem se interrompe (CC, art. 207) e deve ser conhecida de ofício (art. 210).","dispositivo":"CC, arts. 207 a 211","tags":["prazos"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Prescrição e decadência"]]},{"termo":"Repristinação","extenso":"Repristinação","pratica":"Lei revogada não \"ressuscita\" sozinha só porque a lei que a revogou caiu.","tecnica":"Salvo disposição em contrário, a lei revogada não se restaura por ter a lei revogadora perdido a vigência (LINDB, art. 2º, § 3º).","dispositivo":"LINDB, art. 2º, § 3º","tags":["LINDB"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Conflito das leis no tempo e eficácia da lei no espaço"],["Noções de Direito Civil","LINDB: vigência, aplicação, interpretação e integração das leis"]]},{"termo":"Ab-rogação e derrogação","extenso":"Revogação total e parcial","pratica":"Ab-rogação é revogar a lei inteira; derrogação é revogar só uma parte.","tecnica":"A revogação pode ser expressa ou tácita (quando a lei nova é incompatível ou regula inteiramente a matéria; LINDB, art. 2º, § 1º).","dispositivo":"LINDB, art. 2º","tags":["LINDB"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","LINDB: vigência, aplicação, interpretação e integração das leis"],["Noções de Direito Civil","Conflito das leis no tempo e eficácia da lei no espaço"]]},{"termo":"Integração da lei","extenso":"Analogia, costumes e princípios gerais do direito","pratica":"Quando a lei não fala nada, o juiz decide pelo caso parecido, pelos costumes ou pelos princípios.","tecnica":"LINDB, art. 4º. O juiz não pode deixar de decidir alegando lacuna (CPC, art. 140).","dispositivo":"LINDB, art. 4º","tags":["LINDB"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","LINDB: vigência, aplicação, interpretação e integração das leis"]]},{"termo":"Direito adquirido","extenso":"Ato jurídico perfeito, direito adquirido e coisa julgada","pratica":"A lei nova não pode desfazer o que já estava garantido.","tecnica":"A lei em vigor terá efeito imediato e geral, respeitados o ato jurídico perfeito, o direito adquirido e a coisa julgada (LINDB, art. 6º; CF, art. 5º, XXXVI).","dispositivo":"LINDB, art. 6º; CF, art. 5º, XXXVI","tags":["LINDB"],"materias":["Noções de Direito Civil","Noções de Direito Constitucional"],"topicos":[["Noções de Direito Civil","Conflito das leis no tempo e eficácia da lei no espaço"],["Noções de Direito Constitucional","Direitos e deveres individuais e coletivos"]]},{"termo":"Litisconsórcio necessário","extenso":"Litisconsórcio necessário","pratica":"É quando a lei ou a relação jurídica obriga várias pessoas a estarem juntas no processo.","tecnica":"Por disposição de lei ou quando a natureza da relação exigir que a eficácia da sentença dependa da citação de todos (CPC, art. 114).","dispositivo":"CPC, art. 114","tags":["partes"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Litisconsórcio"]]},{"termo":"Litisconsórcio unitário","extenso":"Litisconsórcio unitário","pratica":"É quando o juiz tem que decidir igual para todos os litisconsortes.","tecnica":"Quando, pela natureza da relação, o juiz tiver de decidir de modo uniforme para todos (CPC, art. 116). Diferente do simples.","dispositivo":"CPC, art. 116","tags":["partes"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Litisconsórcio"]]},{"termo":"Assistência","extenso":"Assistência (intervenção de terceiros)","pratica":"É um terceiro entrar no processo para ajudar uma das partes porque também tem interesse.","tecnica":"Simples ou litisconsorcial; exige interesse jurídico (CPC, arts. 119 a 124).","dispositivo":"CPC, arts. 119 a 124","tags":["intervenção de terceiros"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Intervenção de terceiros"]]},{"termo":"Denunciação da lide","extenso":"Denunciação da lide","pratica":"É trazer para o processo quem vai ter que reembolsar você se perder, como a seguradora.","tecnica":"Admissível ao alienante (evicção) e a quem está obrigado, por lei ou contrato, a indenizar em ação regressiva (CPC, art. 125).","dispositivo":"CPC, art. 125","tags":["intervenção de terceiros"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Intervenção de terceiros"]]},{"termo":"Chamamento ao processo","extenso":"Chamamento ao processo","pratica":"É o devedor chamar os outros devedores (como o fiador chamar o devedor principal) para responderem juntos.","tecnica":"Hipóteses do CPC, art. 130 (afiançado, demais fiadores, devedores solidários).","dispositivo":"CPC, art. 130","tags":["intervenção de terceiros"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Intervenção de terceiros"]]},{"termo":"Amicus curiae","extenso":"Amigo da corte","pratica":"É uma entidade especializada que entra no processo para ajudar o juiz com informações.","tecnica":"Admitido pela relevância da matéria, especificidade do tema ou repercussão social (CPC, art. 138). Não pode recorrer, salvo embargos de declaração e no IRDR.","dispositivo":"CPC, art. 138","tags":["intervenção de terceiros"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Intervenção de terceiros"]]},{"termo":"Competência absoluta","extenso":"Competência absoluta","pratica":"É a regra de competência que não pode ser mudada pelas partes, como a por matéria.","tecnica":"Em razão da matéria, da pessoa ou da função. Pode ser alegada a qualquer tempo e deve ser declarada de ofício (CPC, art. 64, § 1º).","dispositivo":"CPC, arts. 62 e 64","tags":["competência"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Competência: disposições gerais, modificação e incompetência"]]},{"termo":"Competência relativa","extenso":"Competência relativa","pratica":"É a competência por território ou valor, que se prorroga se ninguém reclamar.","tecnica":"Deve ser alegada em preliminar de contestação, senão prorroga (CPC, art. 65). Não pode ser declarada de ofício (Súmula 33 do STJ).","dispositivo":"CPC, arts. 63 e 65","tags":["competência"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Competência: disposições gerais, modificação e incompetência"]]},{"termo":"Conexão","extenso":"Conexão","pratica":"Duas ações com o mesmo pedido ou a mesma causa vão para o mesmo juiz para não haver decisões opostas.","tecnica":"Ações com o mesmo pedido ou causa de pedir (CPC, art. 55). Reunião no juízo prevento (art. 58).","dispositivo":"CPC, art. 55","tags":["competência"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Competência: disposições gerais, modificação e incompetência"]]},{"termo":"Continência","extenso":"Continência","pratica":"Uma ação \"contém\" a outra: mesmas partes e causa, mas um pedido maior.","tecnica":"Identidade de partes e causa de pedir, sendo o pedido de uma mais amplo (CPC, art. 56).","dispositivo":"CPC, arts. 56 e 57","tags":["competência"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Competência: disposições gerais, modificação e incompetência"]]},{"termo":"Preclusão","extenso":"Preclusão","pratica":"É perder a chance de praticar um ato no processo.","tecnica":"Temporal (perdeu o prazo), lógica (ato incompatível com o anterior) e consumativa (já praticou o ato). CPC, art. 507.","dispositivo":"CPC, arts. 223 e 507","tags":["processo"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Pressupostos processuais e preclusão"]]},{"termo":"Impedimento","extenso":"Impedimento do juiz","pratica":"Situação objetiva que proíbe o juiz de atuar, como ser parente de uma das partes.","tecnica":"Hipóteses do CPC, art. 144. Pode ser alegado a qualquer tempo e fundamenta ação rescisória.","dispositivo":"CPC, art. 144","tags":["juiz"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Juiz: poderes, deveres, responsabilidade, impedimento e suspeição"]]},{"termo":"Suspeição","extenso":"Suspeição do juiz","pratica":"Situação mais subjetiva que põe em dúvida a imparcialidade, como ser amigo íntimo de uma parte.","tecnica":"Hipóteses do CPC, art. 145. Deve ser alegada em 15 dias do conhecimento do fato (art. 146).","dispositivo":"CPC, arts. 145 e 146","tags":["juiz"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Juiz: poderes, deveres, responsabilidade, impedimento e suspeição"]]},{"termo":"Revelia","extenso":"Revelia","pratica":"É o réu não responder à ação. Em regra, os fatos alegados pelo autor passam a ser considerados verdadeiros.","tecnica":"Presunção de veracidade dos fatos (CPC, art. 344), com exceções do art. 345 (pluralidade de réus em que algum contesta, direitos indisponíveis etc.).","dispositivo":"CPC, arts. 344 e 345","tags":["defesa"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Contestação, reconvenção e revelia"]]},{"termo":"Reconvenção","extenso":"Reconvenção","pratica":"É o réu, na própria contestação, fazer um pedido contra o autor.","tecnica":"Proposta na contestação, conexa com a ação principal ou com o fundamento da defesa (CPC, art. 343).","dispositivo":"CPC, art. 343","tags":["defesa"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Contestação, reconvenção e revelia"]]},{"termo":"Tutela de urgência","extenso":"Tutela provisória de urgência","pratica":"É a decisão rápida quando há risco de o direito se perder com a demora.","tecnica":"Exige probabilidade do direito e perigo de dano ou risco ao resultado útil do processo (CPC, art. 300). Pode ser antecipada ou cautelar, antecedente ou incidental.","dispositivo":"CPC, art. 300","tags":["tutela provisória"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Tutela provisória e tutela de urgência"]]},{"termo":"Tutela de evidência","extenso":"Tutela provisória da evidência","pratica":"É a decisão rápida quando o direito é tão claro que não precisa provar urgência.","tecnica":"Independe de perigo de dano; hipóteses do CPC, art. 311.","dispositivo":"CPC, art. 311","tags":["tutela provisória"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Tutela provisória e tutela de urgência"]]},{"termo":"Estabilização da tutela","extenso":"Estabilização da tutela antecipada antecedente","pratica":"Se o réu não recorrer da tutela antecipada pedida antes da ação principal, ela continua valendo.","tecnica":"CPC, art. 304: o processo é extinto e a decisão se estabiliza; pode ser revista em ação própria em até 2 anos. Não faz coisa julgada.","dispositivo":"CPC, art. 304","tags":["tutela provisória"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Tutela provisória e tutela de urgência"]]},{"termo":"Sentença terminativa","extenso":"Sentença sem resolução de mérito","pratica":"É a sentença que encerra o processo sem decidir quem tem razão.","tecnica":"Hipóteses do CPC, art. 485 (indeferimento da inicial, abandono, ausência de pressupostos, perempção etc.). Em regra, permite nova ação.","dispositivo":"CPC, art. 485","tags":["sentença"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Sentença e coisa julgada"],["Noções de Direito Processual Civil","Formação, suspensão e extinção do processo"]]},{"termo":"Sentença definitiva","extenso":"Sentença com resolução de mérito","pratica":"É a sentença que decide quem tem razão.","tecnica":"Hipóteses do CPC, art. 487 (acolher ou rejeitar o pedido, decadência ou prescrição, homologação de acordo etc.). Faz coisa julgada material.","dispositivo":"CPC, art. 487","tags":["sentença"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Sentença e coisa julgada"]]},{"termo":"Coisa julgada material","extenso":"Coisa julgada material","pratica":"É quando a decisão de mérito não cabe mais recurso e não pode ser discutida de novo.","tecnica":"Autoridade que torna imutável e indiscutível a decisão de mérito não mais sujeita a recurso (CPC, art. 502).","dispositivo":"CPC, art. 502","tags":["sentença"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Sentença e coisa julgada"]]},{"termo":"Despacho, decisão interlocutória e sentença","extenso":"Pronunciamentos do juiz","pratica":"Despacho só movimenta o processo; decisão interlocutória resolve uma questão no meio; sentença encerra a fase.","tecnica":"CPC, art. 203. Despachos não têm conteúdo decisório e são irrecorríveis (art. 1.001).","dispositivo":"CPC, art. 203","tags":["atos judiciais"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Atos judiciais: despachos, decisões interlocutórias e sentenças"]]},{"termo":"Apelação","extenso":"Apelação","pratica":"É o recurso contra a sentença.","tecnica":"Prazo de 15 dias úteis; em regra, tem efeito suspensivo (CPC, arts. 1.009 e 1.012).","dispositivo":"CPC, arts. 1.009 a 1.014","tags":["recursos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Apelação, agravo de instrumento e agravo interno"]]},{"termo":"Agravo de instrumento","extenso":"Agravo de instrumento","pratica":"É o recurso contra algumas decisões tomadas no meio do processo.","tecnica":"Cabível nas hipóteses do CPC, art. 1.015; prazo de 15 dias úteis; interposto diretamente no tribunal.","dispositivo":"CPC, art. 1.015","tags":["recursos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Apelação, agravo de instrumento e agravo interno"]]},{"termo":"Agravo interno","extenso":"Agravo interno","pratica":"É o recurso contra decisão de um relator só, para o colegiado decidir.","tecnica":"Contra decisão monocrática do relator, para o órgão colegiado (CPC, art. 1.021). Prazo de 15 dias úteis.","dispositivo":"CPC, art. 1.021","tags":["recursos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Apelação, agravo de instrumento e agravo interno"]]},{"termo":"Embargos de declaração","extenso":"Embargos de declaração","pratica":"É pedir ao próprio juiz que esclareça ou complete a decisão.","tecnica":"Contra obscuridade, contradição, omissão ou erro material (CPC, art. 1.022). Prazo de 5 dias úteis; interrompem o prazo dos demais recursos (art. 1.026).","dispositivo":"CPC, arts. 1.022 a 1.026","tags":["recursos","prazos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Embargos de declaração"]]},{"termo":"REsp","extenso":"Recurso especial","pratica":"É o recurso ao STJ quando a decisão contraria lei federal.","tecnica":"CF, art. 105, III. Não serve para reexaminar provas (Súmula 7 do STJ).","dispositivo":"CF, art. 105, III","tags":["recursos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Recursos para o STF e para o STJ"]]},{"termo":"RE","extenso":"Recurso extraordinário","pratica":"É o recurso ao STF quando a decisão contraria a Constituição.","tecnica":"CF, art. 102, III. Exige repercussão geral (§ 3º).","dispositivo":"CF, art. 102, III","tags":["recursos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Recursos para o STF e para o STJ"]]},{"termo":"Prazos em dias úteis","extenso":"Contagem de prazos processuais","pratica":"No processo civil, só contam os dias úteis.","tecnica":"CPC, art. 219. Prazo padrão de recursos: 15 dias, exceto embargos de declaração (5). Suspensão entre 20 de dezembro e 20 de janeiro (art. 220).","dispositivo":"CPC, arts. 219 e 220","tags":["prazos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Atos processuais: forma, tempo, lugar e prazos"]]},{"termo":"Prazo em dobro","extenso":"Prazo em dobro","pratica":"Alguns têm o dobro do prazo: Ministério Público, Fazenda Pública e Defensoria.","tecnica":"CPC, arts. 180, 183 e 186. Litisconsortes com procuradores de escritórios diferentes, em autos físicos, também (art. 229).","dispositivo":"CPC, arts. 180, 183, 186 e 229","tags":["prazos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Atos processuais: forma, tempo, lugar e prazos"],["Noções de Direito Processual Civil","Ministério Público, Advocacia Pública e Defensoria Pública no processo"]]},{"termo":"Multa do cumprimento de sentença","extenso":"Multa e honorários do art. 523","pratica":"Se o devedor não paga em 15 dias depois de intimado, a dívida aumenta 10% de multa e mais 10% de honorários.","tecnica":"CPC, art. 523, § 1º.","dispositivo":"CPC, art. 523","tags":["execução"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Cumprimento de sentença e impugnação"]]},{"termo":"Princípio da inércia","extenso":"Princípio da inércia (demanda)","pratica":"O juiz só age quando alguém pede.","tecnica":"O processo começa por iniciativa da parte e se desenvolve por impulso oficial, salvo exceções legais (CPC, art. 2º).","dispositivo":"CPC, art. 2º","tags":["princípios"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Jurisdição e princípio da inércia"]]},{"termo":"Juiz natural","extenso":"Princípio do juiz natural","pratica":"O caso é julgado pelo juiz definido antes pelas regras, não escolhido depois.","tecnica":"Não haverá juízo ou tribunal de exceção (CF, art. 5º, XXXVII) e ninguém será processado nem sentenciado senão pela autoridade competente (LIII).","dispositivo":"CF, art. 5º, XXXVII e LIII","tags":["princípios"],"materias":["Noções de Direito Processual Civil","Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Civil","Princípios do processo: devido processo legal, contraditório, ampla defesa e juiz natural"],["Noções de Direito Processual Penal","Disposições constitucionais aplicáveis ao processo penal"]]},{"termo":"Contraditório e ampla defesa","extenso":"Contraditório e ampla defesa","pratica":"As partes têm direito de saber de tudo e responder, com todos os meios de defesa.","tecnica":"CF, art. 5º, LV. No CPC, o juiz não pode decidir com base em fundamento sobre o qual não deu oportunidade de manifestação (art. 10).","dispositivo":"CF, art. 5º, LV; CPC, arts. 9º e 10","tags":["princípios"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Princípios do processo: devido processo legal, contraditório, ampla defesa e juiz natural"]]},{"termo":"Carta rogatória","extenso":"Carta rogatória","pratica":"É o pedido de um juiz a um juiz de outro país para praticar um ato, como uma citação.","tecnica":"Instrumento de cooperação internacional que depende de juízo de delibação; no Brasil, o exequatur é concedido pelo STJ.","dispositivo":null,"tags":["cooperação"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Cooperação internacional: auxílio direto e carta rogatória"]]},{"termo":"Auxílio direto","extenso":"Auxílio direto","pratica":"É a cooperação entre países sem precisar de decisão do outro juiz, tratada pelas autoridades centrais.","tecnica":"Cabe quando a medida não decorre diretamente de decisão de autoridade jurisdicional estrangeira submetida a delibação no Brasil (CPC, art. 28).","dispositivo":"CPC, arts. 28 a 34","tags":["cooperação"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Cooperação internacional: auxílio direto e carta rogatória"]]},{"termo":"Princípio da legalidade penal","extenso":"Princípio da reserva legal e da anterioridade","pratica":"Só é crime o que a lei disse antes que é crime.","tecnica":"Não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal (CP, art. 1º; CF, art. 5º, XXXIX).","dispositivo":"CP, art. 1º; CF, art. 5º, XXXIX","tags":["princípios"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Princípios da legalidade e da anterioridade"],["Noções de Direito Penal","Disposições constitucionais aplicáveis ao direito penal"]]},{"termo":"Abolitio criminis","extenso":"Abolição do crime","pratica":"É quando uma lei nova deixa de considerar o fato como crime. Todo mundo é beneficiado, até quem já foi condenado.","tecnica":"Cessam a execução e os efeitos penais da sentença condenatória; efeitos civis permanecem (CP, art. 2º). Causa de extinção da punibilidade (art. 107, III).","dispositivo":"CP, arts. 2º e 107, III","tags":["lei penal no tempo"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Lei penal no tempo e no espaço; tempo e lugar do crime"]]},{"termo":"Novatio legis in mellius","extenso":"Lei nova mais benéfica","pratica":"Lei nova mais branda volta para trás e beneficia o réu.","tecnica":"A lei posterior que de qualquer modo favorecer o agente aplica-se aos fatos anteriores, ainda que decididos por sentença transitada em julgado (CP, art. 2º, parágrafo único).","dispositivo":"CP, art. 2º, parágrafo único","tags":["lei penal no tempo"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Lei penal no tempo e no espaço; tempo e lugar do crime"],["Noções de Direito Penal","Interpretação da lei penal, analogia e irretroatividade"]]},{"termo":"Novatio legis in pejus","extenso":"Lei nova mais gravosa","pratica":"Lei nova mais dura não volta para trás.","tecnica":"Irretroatividade da lei penal mais grave (CF, art. 5º, XL).","dispositivo":"CF, art. 5º, XL","tags":["lei penal no tempo"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Lei penal no tempo e no espaço; tempo e lugar do crime"],["Noções de Direito Penal","Interpretação da lei penal, analogia e irretroatividade"]]},{"termo":"Lei excepcional ou temporária","extenso":"Leis penais excepcionais e temporárias","pratica":"Leis feitas para um período ou situação continuam valendo para os fatos daquele período, mesmo depois que acabam.","tecnica":"Ultra-atividade: aplicam-se ao fato praticado durante sua vigência, embora decorrido o período ou cessadas as circunstâncias (CP, art. 3º).","dispositivo":"CP, art. 3º","tags":["lei penal no tempo"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Lei penal excepcional, especial e temporária"]]},{"termo":"Teoria da atividade","extenso":"Tempo do crime","pratica":"O crime acontece no momento da ação, mesmo que o resultado venha depois.","tecnica":"Considera-se praticado o crime no momento da ação ou omissão, ainda que outro seja o momento do resultado (CP, art. 4º). Mnemônico LUTA: Lugar Ubiquidade, Tempo Atividade.","dispositivo":"CP, art. 4º","tags":["lei penal"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Lei penal no tempo e no espaço; tempo e lugar do crime"]]},{"termo":"Teoria da ubiquidade","extenso":"Lugar do crime","pratica":"O crime acontece tanto onde foi a ação quanto onde aconteceu o resultado.","tecnica":"CP, art. 6º: lugar da ação ou omissão, no todo ou em parte, e onde se produziu ou deveria produzir-se o resultado.","dispositivo":"CP, art. 6º","tags":["lei penal"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Lei penal no tempo e no espaço; tempo e lugar do crime"]]},{"termo":"Extraterritorialidade","extenso":"Extraterritorialidade da lei penal","pratica":"Em alguns casos, a lei brasileira vale para crimes cometidos fora do Brasil.","tecnica":"Incondicionada (CP, art. 7º, I: crimes contra a vida ou liberdade do Presidente, contra o patrimônio público, contra a administração por quem está a seu serviço, genocídio por brasileiro ou domiciliado) e condicionada (art. 7º, II, com as condições do § 2º).","dispositivo":"CP, art. 7º","tags":["lei penal no espaço"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Territorialidade e extraterritorialidade"]]},{"termo":"Fato típico","extenso":"Fato típico","pratica":"É a conduta que bate com a descrição de um crime na lei.","tecnica":"Elementos: conduta, resultado, nexo causal e tipicidade. Primeiro substrato do conceito analítico de crime (fato típico, ilícito e culpável).","dispositivo":null,"tags":["teoria do crime"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Teoria do crime: tipo penal objetivo e subjetivo"]]},{"termo":"Dolo eventual","extenso":"Dolo eventual","pratica":"É prever que pode causar o resultado e não se importar: \"se acontecer, aconteceu\".","tecnica":"O agente assume o risco de produzir o resultado (CP, art. 18, I, parte final). Diferente da culpa consciente, em que acredita sinceramente que o resultado não ocorrerá.","dispositivo":"CP, art. 18, I","tags":["teoria do crime"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Teoria do crime: tipo penal objetivo e subjetivo"]]},{"termo":"Culpa","extenso":"Crime culposo","pratica":"É causar o resultado sem querer, por descuido: imprudência, negligência ou imperícia.","tecnica":"CP, art. 18, II. Só há crime culposo quando a lei prevê expressamente (parágrafo único).","dispositivo":"CP, art. 18, II","tags":["teoria do crime"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Teoria do crime: tipo penal objetivo e subjetivo"]]},{"termo":"Excludentes de ilicitude","extenso":"Causas de exclusão da ilicitude","pratica":"São situações em que o fato é típico mas não é crime: legítima defesa, por exemplo.","tecnica":"Estado de necessidade, legítima defesa, estrito cumprimento de dever legal e exercício regular de direito (CP, art. 23). Excesso doloso ou culposo é punível.","dispositivo":"CP, art. 23","tags":["ilicitude"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Ilicitude e causas excludentes"]]},{"termo":"Legítima defesa","extenso":"Legítima defesa","pratica":"É se defender, com moderação, de uma agressão injusta que está acontecendo ou vai acontecer.","tecnica":"Uso moderado dos meios necessários para repelir injusta agressão, atual ou iminente, a direito seu ou de outrem (CP, art. 25).","dispositivo":"CP, art. 25","tags":["ilicitude"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Ilicitude e causas excludentes"]]},{"termo":"Estado de necessidade","extenso":"Estado de necessidade","pratica":"É sacrificar um bem para salvar outro de um perigo que você não causou.","tecnica":"Salvar de perigo atual, que não provocou por sua vontade nem podia evitar, direito próprio ou alheio cujo sacrifício não era razoável exigir (CP, art. 24).","dispositivo":"CP, art. 24","tags":["ilicitude"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Ilicitude e causas excludentes"]]},{"termo":"Culpabilidade","extenso":"Culpabilidade","pratica":"É a reprovação da pessoa: ela podia entender e agir de outro jeito?","tecnica":"Elementos: imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa. As dirimentes excluem a culpabilidade.","dispositivo":null,"tags":["culpabilidade"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Culpabilidade e causas dirimentes"]]},{"termo":"Inimputabilidade","extenso":"Inimputabilidade","pratica":"É não poder ser responsabilizado penalmente por não entender o que fez, como menor de 18 ou por doença mental.","tecnica":"Menores de 18 anos (CP, art. 27; CF, art. 228) e doença mental ou desenvolvimento mental incompleto que retire a capacidade de entender ou de se determinar (art. 26).","dispositivo":"CP, arts. 26 a 28","tags":["culpabilidade"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Culpabilidade e causas dirimentes"]]},{"termo":"Erro de tipo","extenso":"Erro sobre elemento do tipo","pratica":"É se enganar sobre o fato: levar a mala de outra pessoa achando que é sua.","tecnica":"Exclui o dolo, permitindo punição por culpa se prevista (CP, art. 20).","dispositivo":"CP, art. 20","tags":["erro"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Teoria do crime: tipo penal objetivo e subjetivo"]]},{"termo":"Erro de proibição","extenso":"Erro sobre a ilicitude do fato","pratica":"É saber o que está fazendo, mas achar que é permitido.","tecnica":"Se inevitável, isenta de pena; se evitável, diminui de 1/6 a 1/3 (CP, art. 21). O desconhecimento da lei é inescusável.","dispositivo":"CP, art. 21","tags":["erro"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Culpabilidade e causas dirimentes"]]},{"termo":"Funcionário público (penal)","extenso":"Conceito penal de funcionário público","pratica":"Para o Direito Penal, é quem exerce qualquer função pública, mesmo temporária ou sem salário.","tecnica":"CP, art. 327. Equipara-se quem trabalha em entidade paraestatal e em empresa contratada para atividade típica da administração (§ 1º).","dispositivo":"CP, art. 327","tags":["crimes contra a administração"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a administração pública"]]},{"termo":"Peculato","extenso":"Peculato","pratica":"É o servidor desviar ou se apropriar de dinheiro ou bem que tem por causa do cargo.","tecnica":"CP, art. 312. Peculato culposo (§ 2º): a reparação do dano antes da sentença irrecorrível extingue a punibilidade; depois, reduz a pena pela metade (§ 3º).","dispositivo":"CP, art. 312","tags":["crimes contra a administração"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a administração pública"]]},{"termo":"Concussão","extenso":"Concussão","pratica":"É o servidor EXIGIR uma vantagem indevida.","tecnica":"Exigir, para si ou para outrem, direta ou indiretamente, vantagem indevida em razão da função (CP, art. 316).","dispositivo":"CP, art. 316","tags":["crimes contra a administração"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a administração pública"]]},{"termo":"Corrupção passiva","extenso":"Corrupção passiva","pratica":"É o servidor PEDIR, RECEBER ou ACEITAR promessa de vantagem indevida.","tecnica":"Solicitar ou receber, ou aceitar promessa de vantagem indevida em razão da função (CP, art. 317). Distingue-se da concussão pelo verbo: exigir é concussão.","dispositivo":"CP, art. 317","tags":["crimes contra a administração"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a administração pública"]]},{"termo":"Corrupção ativa","extenso":"Corrupção ativa","pratica":"É o particular OFERECER ou PROMETER vantagem a um servidor.","tecnica":"Oferecer ou prometer vantagem indevida a funcionário público para determiná-lo a praticar, omitir ou retardar ato de ofício (CP, art. 333).","dispositivo":"CP, art. 333","tags":["crimes contra a administração"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a administração pública"]]},{"termo":"Prevaricação","extenso":"Prevaricação","pratica":"É o servidor deixar de fazer ou atrasar o trabalho para satisfazer interesse ou sentimento pessoal.","tecnica":"Retardar ou deixar de praticar ato de ofício, ou praticá-lo contra lei, para satisfazer interesse ou sentimento pessoal (CP, art. 319).","dispositivo":"CP, art. 319","tags":["crimes contra a administração"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a administração pública"]]},{"termo":"Condescendência criminosa","extenso":"Condescendência criminosa","pratica":"É o chefe, por indulgência, deixar de punir ou de comunicar a falta do subordinado.","tecnica":"CP, art. 320.","dispositivo":"CP, art. 320","tags":["crimes contra a administração"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a administração pública"]]},{"termo":"Advocacia administrativa","extenso":"Advocacia administrativa","pratica":"É o servidor usar o cargo para defender interesse privado dentro da administração.","tecnica":"Patrocinar, direta ou indiretamente, interesse privado perante a administração, valendo-se da qualidade de funcionário (CP, art. 321).","dispositivo":"CP, art. 321","tags":["crimes contra a administração"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a administração pública"]]},{"termo":"Furto","extenso":"Furto","pratica":"É pegar coisa alheia sem violência.","tecnica":"Subtrair, para si ou para outrem, coisa alheia móvel (CP, art. 155).","dispositivo":"CP, art. 155","tags":["crimes contra o patrimônio"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra o patrimônio"]]},{"termo":"Roubo","extenso":"Roubo","pratica":"É pegar coisa alheia com violência ou grave ameaça.","tecnica":"CP, art. 157: subtração mediante grave ameaça ou violência à pessoa, ou depois de reduzi-la à impossibilidade de resistência.","dispositivo":"CP, art. 157","tags":["crimes contra o patrimônio"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra o patrimônio"]]},{"termo":"Estelionato","extenso":"Estelionato","pratica":"É enganar alguém para conseguir vantagem: o famoso golpe.","tecnica":"Obter vantagem ilícita, induzindo ou mantendo alguém em erro, mediante artifício, ardil ou outro meio fraudulento (CP, art. 171).","dispositivo":"CP, art. 171","tags":["crimes contra o patrimônio"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra o patrimônio"]]},{"termo":"Crime hediondo","extenso":"Crime hediondo","pratica":"São os crimes considerados mais graves, com regras mais duras.","tecnica":"Rol da Lei 8.072/1990. Insuscetíveis de fiança, graça, anistia e indulto (CF, art. 5º, XLIII; Lei 8.072, art. 2º).","dispositivo":"Lei 8.072/1990; CF, art. 5º, XLIII","tags":["legislação especial"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes hediondos (Lei 8.072/1990)"]]},{"termo":"Abuso de autoridade","extenso":"Crimes de abuso de autoridade (Lei 13.869/2019)","pratica":"É o agente público usar o poder para prejudicar alguém, se beneficiar ou por capricho.","tecnica":"Exige finalidade específica: prejudicar outrem, beneficiar a si ou a terceiro, ou mero capricho ou satisfação pessoal. A divergência na interpretação da lei ou na avaliação de fatos e provas não configura crime (art. 1º, §§ 1º e 2º).","dispositivo":"Lei 13.869/2019, art. 1º","tags":["legislação especial"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Abuso de autoridade (Lei 13.869/2019)"]]},{"termo":"Criança e adolescente (ECA)","extenso":"Conceitos do ECA","pratica":"Criança tem até 12 anos incompletos; adolescente, de 12 a 18.","tecnica":"Lei 8.069/1990, art. 2º. Excepcionalmente, o ECA se aplica a pessoas entre 18 e 21 anos.","dispositivo":"Lei 8.069/1990, art. 2º","tags":["ECA"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Estatuto da Criança e do Adolescente"]]},{"termo":"Ato infracional","extenso":"Ato infracional","pratica":"É o \"crime\" praticado por criança ou adolescente.","tecnica":"Conduta descrita como crime ou contravenção penal (ECA, art. 103). Criança recebe medidas de proteção; adolescente, medidas socioeducativas (art. 112).","dispositivo":"Lei 8.069/1990, arts. 103 e 112","tags":["ECA"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Estatuto da Criança e do Adolescente"]]},{"termo":"IP","extenso":"Inquérito policial","pratica":"É a investigação feita pela polícia para descobrir se houve crime e quem foi o autor.","tecnica":"Características: escrito, sigiloso, inquisitivo, dispensável e indisponível. A autoridade policial não pode mandar arquivá-lo (CPP, art. 17).","dispositivo":"CPP, arts. 4º a 23","tags":["inquérito"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Inquérito policial"]]},{"termo":"Notitia criminis","extenso":"Notícia do crime","pratica":"É a polícia ficar sabendo de um crime.","tecnica":"Pode ser espontânea (de cognição imediata), provocada (de cognição mediata, por requisição ou requerimento) ou coercitiva (prisão em flagrante).","dispositivo":null,"tags":["inquérito"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Inquérito policial"]]},{"termo":"Ação penal pública incondicionada","extenso":"Ação penal pública incondicionada","pratica":"O Ministério Público processa sem precisar de autorização de ninguém. É a regra.","tecnica":"Promovida por denúncia do MP (CPP, art. 24). Regidas pela obrigatoriedade e pela indisponibilidade: o MP não pode desistir (art. 42).","dispositivo":"CPP, arts. 24 e 42","tags":["ação penal"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Ação penal"]]},{"termo":"Ação penal pública condicionada","extenso":"Ação penal pública condicionada","pratica":"O Ministério Público só processa se a vítima (representação) ou o Ministro da Justiça (requisição) autorizarem.","tecnica":"A representação é retratável até o oferecimento da denúncia (CPP, art. 25) e tem prazo decadencial de 6 meses (art. 38).","dispositivo":"CPP, arts. 24, 25 e 38","tags":["ação penal"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Ação penal"]]},{"termo":"Ação penal privada","extenso":"Ação penal privada","pratica":"A própria vítima processa, por meio de advogado, com a queixa-crime.","tecnica":"Prazo decadencial de 6 meses do conhecimento da autoria (CPP, art. 38). Regida pela oportunidade e disponibilidade: admite perdão e perempção (arts. 51 e 60).","dispositivo":"CPP, arts. 30, 38 e 60","tags":["ação penal"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Ação penal"]]},{"termo":"Denúncia","extenso":"Denúncia","pratica":"É a peça com que o Ministério Público começa o processo penal.","tecnica":"Inicial da ação penal pública; requisitos no CPP, art. 41. Prazo: 5 dias com réu preso e 15 com réu solto (art. 46).","dispositivo":"CPP, arts. 41 e 46","tags":["ação penal","prazos"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Ação penal"]]},{"termo":"Queixa-crime","extenso":"Queixa-crime","pratica":"É a peça com que a vítima começa a ação penal privada.","tecnica":"Oferecida por advogado com poderes especiais (CPP, art. 44), no prazo decadencial de 6 meses.","dispositivo":"CPP, art. 44","tags":["ação penal"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Ação penal"]]},{"termo":"Perempção","extenso":"Perempção","pratica":"É o autor da ação privada perder o direito de seguir com ela por descuido.","tecnica":"Hipóteses do CPP, art. 60 (deixar de promover o andamento por 30 dias seguidos, não comparecer sem motivo etc.). Só na ação penal exclusivamente privada.","dispositivo":"CPP, art. 60","tags":["ação penal"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Ação penal"]]},{"termo":"Citação por edital","extenso":"Citação por edital (processo penal)","pratica":"É chamar o réu por publicação quando ele não é encontrado.","tecnica":"Se o acusado citado por edital não comparecer nem constituir advogado, ficam suspensos o processo e o prazo prescricional (CPP, art. 366).","dispositivo":"CPP, arts. 361 e 366","tags":["citação"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Citações e intimações"]]},{"termo":"Citação por hora certa","extenso":"Citação por hora certa (processo penal)","pratica":"É a citação quando o réu se esconde para não ser citado.","tecnica":"Admitida no processo penal na forma do CPC (CPP, art. 362). Se o réu não comparecer, recebe defensor dativo.","dispositivo":"CPP, art. 362","tags":["citação"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Citações e intimações"]]},{"termo":"Emendatio libelli","extenso":"Emendatio libelli","pratica":"É o juiz dar outra classificação jurídica ao fato, sem mudar o fato descrito na denúncia.","tecnica":"CPP, art. 383: pode atribuir definição jurídica diversa, ainda que a pena seja mais grave.","dispositivo":"CPP, art. 383","tags":["sentença"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Sentença"]]},{"termo":"Mutatio libelli","extenso":"Mutatio libelli","pratica":"É quando aparece um fato novo na instrução e a acusação precisa ser aditada.","tecnica":"CPP, art. 384: o MP deve aditar a denúncia em 5 dias, com nova oportunidade de defesa.","dispositivo":"CPP, art. 384","tags":["sentença"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Sentença"]]},{"termo":"Absolvição sumária","extenso":"Absolvição sumária","pratica":"É o juiz absolver logo no começo, sem instrução, quando é evidente que não há crime ou punição.","tecnica":"No procedimento comum, hipóteses do CPP, art. 397; no Júri, do art. 415.","dispositivo":"CPP, arts. 397 e 415","tags":["procedimentos"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Processo comum e instrução criminal"],["Noções de Direito Processual Penal","Júri: acusação, instrução preliminar, pronúncia, impronúncia e absolvição sumária"]]},{"termo":"Pronúncia","extenso":"Decisão de pronúncia","pratica":"É o juiz mandar o réu a julgamento pelo júri.","tecnica":"Quando convencido da materialidade e de indícios suficientes de autoria ou participação (CPP, art. 413).","dispositivo":"CPP, art. 413","tags":["Júri"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Júri: acusação, instrução preliminar, pronúncia, impronúncia e absolvição sumária"]]},{"termo":"Impronúncia","extenso":"Decisão de impronúncia","pratica":"É o juiz não mandar a júri por falta de provas suficientes. Pode haver nova denúncia com prova nova.","tecnica":"CPP, art. 414: enquanto não extinta a punibilidade, pode ser formulada nova denúncia se houver prova nova.","dispositivo":"CPP, art. 414","tags":["Júri"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Júri: acusação, instrução preliminar, pronúncia, impronúncia e absolvição sumária"]]},{"termo":"Desaforamento","extenso":"Desaforamento","pratica":"É mudar o julgamento do júri para outra comarca, por exemplo por dúvida sobre a imparcialidade dos jurados.","tecnica":"Interesse da ordem pública, dúvida sobre a imparcialidade do júri ou a segurança do acusado (CPP, art. 427), ou excesso de serviço (art. 428).","dispositivo":"CPP, arts. 427 e 428","tags":["Júri"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Júri: preparação do plenário, alistamento dos jurados, desaforamento e pauta"]]},{"termo":"Conselho de Sentença","extenso":"Conselho de Sentença","pratica":"São os 7 jurados sorteados que julgam o réu no plenário.","tecnica":"O Tribunal do Júri é composto pelo juiz presidente e 25 jurados sorteados; 7 formam o Conselho de Sentença (CPP, art. 447).","dispositivo":"CPP, art. 447","tags":["Júri"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Júri: composição, Conselho de Sentença, sessões e instrução em plenário"]]},{"termo":"Princípios do Júri","extenso":"Princípios constitucionais do Tribunal do Júri","pratica":"O júri tem garantias especiais na Constituição.","tecnica":"Plenitude de defesa, sigilo das votações, soberania dos veredictos e competência para crimes dolosos contra a vida (CF, art. 5º, XXXVIII).","dispositivo":"CF, art. 5º, XXXVIII","tags":["Júri"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Disposições constitucionais aplicáveis ao processo penal"],["Noções de Direito Processual Penal","Júri: composição, Conselho de Sentença, sessões e instrução em plenário"]]},{"termo":"Quesitos","extenso":"Quesitos do Júri","pratica":"São as perguntas que os jurados respondem com \"sim\" ou \"não\" para decidir o caso.","tecnica":"Ordem do CPP, art. 483: materialidade, autoria ou participação, se o acusado deve ser absolvido, causas de diminuição e qualificadoras ou causas de aumento.","dispositivo":"CPP, art. 483","tags":["Júri"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Júri: debates, quesitos e votação, sentença, ata e atribuições do presidente"]]},{"termo":"Prisão em flagrante","extenso":"Prisão em flagrante","pratica":"É prender quem está cometendo ou acabou de cometer o crime.","tecnica":"Espécies do CPP, art. 302: próprio (I e II), impróprio (III, perseguição) e presumido (IV, encontrado logo depois com instrumentos ou objetos).","dispositivo":"CPP, art. 302","tags":["prisão"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Prisão e liberdade provisória"]]},{"termo":"Audiência de custódia","extenso":"Audiência de custódia","pratica":"É levar o preso ao juiz em até 24 horas para checar se a prisão foi legal.","tecnica":"CPP, art. 310: o juiz relaxa a prisão ilegal, converte em preventiva ou concede liberdade provisória.","dispositivo":"CPP, art. 310","tags":["prisão"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Prisão e liberdade provisória"]]},{"termo":"Prisão preventiva","extenso":"Prisão preventiva","pratica":"É prender antes da condenação, quando há risco concreto se a pessoa ficar solta.","tecnica":"Para garantia da ordem pública ou econômica, conveniência da instrução ou aplicação da lei penal, com prova do crime, indício suficiente de autoria e perigo gerado pela liberdade (CPP, art. 312). Não pode ser decretada de ofício (art. 311).","dispositivo":"CPP, arts. 311 a 316","tags":["prisão"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Prisão e liberdade provisória"]]},{"termo":"Prisão temporária","extenso":"Prisão temporária","pratica":"É uma prisão curta, só durante a investigação.","tecnica":"Lei 7.960/1989: 5 dias, prorrogáveis por mais 5; nos crimes hediondos, 30 + 30 (Lei 8.072, art. 2º, § 4º). Só no inquérito.","dispositivo":"Lei 7.960/1989","tags":["prisão"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Prisão e liberdade provisória"]]},{"termo":"Fiança","extenso":"Fiança","pratica":"É pagar um valor para responder ao processo em liberdade.","tecnica":"Inafiançáveis: racismo, tortura, tráfico, terrorismo, crimes hediondos e ação de grupos armados contra a ordem constitucional (CF, art. 5º, XLII a XLIV; CPP, art. 323).","dispositivo":"CPP, arts. 322 a 350","tags":["prisão"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Prisão e liberdade provisória"]]},{"termo":"Defesa preliminar do servidor","extenso":"Resposta preliminar nos crimes funcionais","pratica":"Antes de receber a denúncia contra servidor, o juiz o notifica para se defender em 15 dias.","tecnica":"Nos crimes afiançáveis de responsabilidade dos funcionários públicos (CPP, art. 514). A Súmula 330 do STJ dispensa a resposta quando a denúncia se baseia em inquérito policial.","dispositivo":"CPP, arts. 513 a 518","tags":["procedimentos"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Crimes de responsabilidade dos funcionários públicos: processo e julgamento"]]},{"termo":"Habeas corpus preventivo e liberatório","extenso":"Espécies de habeas corpus","pratica":"Preventivo é antes da prisão, com salvo-conduto; liberatório é para soltar quem já está preso.","tecnica":"CPP, arts. 647 a 667. Pode ser concedido de ofício pelo juiz ou tribunal (art. 654, § 2º).","dispositivo":"CPP, arts. 647 a 667","tags":["habeas corpus"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Habeas corpus e seu processo"]]}]$termos$::jsonb;
  vinculos jsonb := $vinculos$[{"termo":"CF","materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Constituição: conceito e classificações"]]},{"termo":"STF","materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Órgãos do Poder Judiciário e competências"]]},{"termo":"STJ","materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Órgãos do Poder Judiciário e competências"]]},{"termo":"CNJ","materias":["Noções de Direito Constitucional","Regimento Interno do TJDFT"],"topicos":[["Noções de Direito Constitucional","Conselho Nacional de Justiça: composição e competência"],["Regimento Interno do TJDFT","Disposições iniciais e composição do Tribunal"]]},{"termo":"TJDFT","materias":["Lei de Organização Judiciária do DF e dos Territórios","Regimento Interno do TJDFT"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Tribunal de Justiça: composição e competência"],["Regimento Interno do TJDFT","Disposições iniciais e composição do Tribunal"]]},{"termo":"TRF","materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Órgãos do Poder Judiciário e competências"]]},{"termo":"LOA","materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Orçamento público: princípios orçamentários"],["Noções de Administração de Recursos Humanos e Gestão Pública","Diretrizes orçamentárias, processo orçamentário e emendas ao orçamento"]]},{"termo":"LDO","materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Diretrizes orçamentárias, processo orçamentário e emendas ao orçamento"]]},{"termo":"PPA","materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Diretrizes orçamentárias, processo orçamentário e emendas ao orçamento"]]},{"termo":"LINDB","materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","LINDB: vigência, aplicação, interpretação e integração das leis"]]},{"termo":"CPC","materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Princípios do processo: devido processo legal, contraditório, ampla defesa e juiz natural"]]},{"termo":"CPP","materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Disposições preliminares do CPP"]]},{"termo":"CP","materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Princípios da legalidade e da anterioridade"]]},{"termo":"CC","materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Pessoas naturais: personalidade e capacidade"]]},{"termo":"PAD","materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"],["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Sindicância","materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"],["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"MS","materias":["Noções de Direito Constitucional","Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Constitucional","Direitos e deveres individuais e coletivos"],["Noções de Direito Processual Civil","Controle judicial dos atos administrativos e mandado de segurança"]]},{"termo":"HC","materias":["Noções de Direito Constitucional","Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Constitucional","Direitos e deveres individuais e coletivos"],["Noções de Direito Processual Penal","Habeas corpus e seu processo"]]},{"termo":"HD","materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Direitos e deveres individuais e coletivos"]]},{"termo":"MI","materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Direitos e deveres individuais e coletivos"]]},{"termo":"Ação popular","materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Direitos e deveres individuais e coletivos"]]},{"termo":"ADI","materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Órgãos do Poder Judiciário e competências"]]},{"termo":"ADC","materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Órgãos do Poder Judiciário e competências"]]},{"termo":"ADPF","materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Órgãos do Poder Judiciário e competências"]]},{"termo":"MP (medida provisória)","materias":["Noções de Direito Constitucional","Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Diretrizes orçamentárias, processo orçamentário e emendas ao orçamento"]]},{"termo":"MP (Ministério Público)","materias":["Noções de Direito Constitucional","Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Constitucional","Funções essenciais à Justiça: Ministério Público"],["Noções de Direito Processual Civil","Ministério Público, Advocacia Pública e Defensoria Pública no processo"]]},{"termo":"DPU","materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Funções essenciais à Justiça: advocacia e Defensoria Pública"]]},{"termo":"AGU","materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Funções essenciais à Justiça: advocacia e Defensoria Pública"]]},{"termo":"PGR","materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Funções essenciais à Justiça: Ministério Público"]]},{"termo":"Vacatio legis","materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","LINDB: vigência, aplicação, interpretação e integração das leis"]]},{"termo":"Quórum","materias":["Noções de Direito Constitucional"],"topicos":[]},{"termo":"Maioria simples","materias":["Noções de Direito Constitucional"],"topicos":[]},{"termo":"Maioria absoluta","materias":["Noções de Direito Constitucional"],"topicos":[]},{"termo":"Sanção","materias":["Noções de Direito Constitucional"],"topicos":[]},{"termo":"Veto","materias":["Noções de Direito Constitucional"],"topicos":[]},{"termo":"Promulgação","materias":["Noções de Direito Constitucional"],"topicos":[]},{"termo":"Publicação","materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","LINDB: vigência, aplicação, interpretação e integração das leis"]]},{"termo":"Provimento","materias":["Noções de Direito Administrativo","Noções de Direito Constitucional"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"],["Noções de Direito Constitucional","Servidores públicos"]]},{"termo":"Vacância","materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Remoção","materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Redistribuição","materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Estágio probatório","materias":["Noções de Direito Administrativo","Noções de Direito Constitucional"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"],["Noções de Direito Constitucional","Servidores públicos"]]},{"termo":"Estabilidade","materias":["Noções de Direito Administrativo","Noções de Direito Constitucional"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"],["Noções de Direito Constitucional","Servidores públicos"]]}]$vinculos$::jsonb;
  pares jsonb := $pares$[["Coesão","Coerência"],["Anáfora","Catáfora"],["Denotação","Conotação"],["Parônimos","Homônimos"],["Próclise","Ênclise"],["Próclise","Mesóclise"],["Regência verbal","Regência nominal"],["Concordância verbal","Concordância nominal"],["Oração coordenada","Oração subordinada"],["Conjunção adversativa","Conjunção concessiva"],["Oração adjetiva restritiva","Oração adjetiva explicativa"],["Voz passiva sintética","Índice de indeterminação do sujeito"],["Tipo textual","Gênero textual"],["Derivação","Composição"],["Abordagem do tema","Fuga ao tema"],["Coesão","Progressão textual"],["Ética","Moral"],["Deveres do servidor","Proibições do servidor"],["Advertência","Suspensão"],["Demissão","Cassação de aposentadoria"],["Demissão","Destituição de cargo em comissão"],["Abandono de cargo","Inassiduidade habitual"],["Enriquecimento ilícito","Lesão ao erário"],["Lesão ao erário","Improbidade contra princípios"],["PAD","Demissão"],["Tribunal Pleno","Conselho Especial"],["Conselho da Magistratura","CNJ"],["Autuação","Juntada"],["DJe","Intimação eletrônica"],["Descrição de cargo","Análise de cargo"],["Pirâmide de Maslow","Teoria dos dois fatores"],["Missão","Visão de futuro"],["Administração patrimonialista","Administração burocrática"],["Administração burocrática","Administração gerencial"],["Eficiência","Eficácia"],["Eficácia","Efetividade"],["Empenho","Liquidação"],["Liquidação","Pagamento"],["Restos a pagar","DEA"],["Crédito suplementar","Crédito especial"],["Crédito especial","Crédito extraordinário"],["Brasileiro nato","Brasileiro naturalizado"],["Competência privativa","Competência concorrente"],["Competência comum","Competência concorrente"],["Administração direta","Administração indireta"],["Desconcentração","Descentralização"],["Empresa pública","Sociedade de economia mista"],["Autarquia","Empresa pública"],["Excesso de poder","Desvio de finalidade"],["Anulação","Revogação"],["Dispensa de licitação","Inexigibilidade de licitação"],["Poder hierárquico","Poder disciplinar"],["Capacidade de direito","Capacidade de fato"],["Absolutamente incapaz","Relativamente incapaz"],["Prescrição","Decadência"],["Nulidade","Anulabilidade"],["Associação","Fundação"],["Competência absoluta","Competência relativa"],["Conexão","Continência"],["Impedimento","Suspeição"],["Denunciação da lide","Chamamento ao processo"],["Tutela de urgência","Tutela de evidência"],["Sentença terminativa","Sentença definitiva"],["Apelação","Agravo de instrumento"],["REsp","RE"],["RE","Repercussão geral"],["Abolitio criminis","Novatio legis in mellius"],["Novatio legis in mellius","Novatio legis in pejus"],["Teoria da atividade","Teoria da ubiquidade"],["Dolo eventual","Culpa"],["Legítima defesa","Estado de necessidade"],["Erro de tipo","Erro de proibição"],["Concussão","Corrupção passiva"],["Corrupção passiva","Corrupção ativa"],["Prevaricação","Corrupção passiva"],["Furto","Roubo"],["Ação penal pública incondicionada","Ação penal pública condicionada"],["Ação penal pública condicionada","Ação penal privada"],["Denúncia","Queixa-crime"],["Emendatio libelli","Mutatio libelli"],["Pronúncia","Impronúncia"],["Prisão preventiva","Prisão temporária"],["Citação por edital","Citação por hora certa"],["HC","Habeas corpus preventivo e liberatório"],["Estabilidade","Garantias da magistratura"],["Peculato","Concussão"]]$pares$::jsonb;
  t jsonb;
  p jsonb;
  a uuid;
  b uuid;
  ids_materias uuid[];
  ids_topicos uuid[];
begin
  if uid is null then
    raise exception 'É preciso estar logada para preparar a nomenclatura.';
  end if;

  insert into public.configuracoes (user_id) values (uid) on conflict (user_id) do nothing;
  if (select termos_2022 from public.configuracoes where user_id = uid) then
    return;
  end if;

  -- Termos novos (pula os que já existem com o mesmo nome).
  for t in select * from jsonb_array_elements(termos) loop
    if exists (select 1 from public.termos where user_id = uid and lower(termo) = lower(t ->> 'termo')) then
      continue;
    end if;
    select coalesce(array_agg(id), '{}') into ids_materias from public.materias
    where user_id = uid and nome in (select jsonb_array_elements_text(t -> 'materias'));
    select coalesce(array_agg(tp.id), '{}') into ids_topicos
    from public.topicos tp
    join public.materias mt on mt.id = tp.materia_id
    where tp.user_id = uid
      and exists (
        select 1 from jsonb_array_elements(t -> 'topicos') par
        where par ->> 0 = mt.nome and par ->> 1 = tp.nome
      );
    insert into public.termos (user_id, termo, extenso, pratica, tecnica, dispositivo, tags, materia_ids, topico_ids)
    values (
      uid, t ->> 'termo', t ->> 'extenso', t ->> 'pratica', t ->> 'tecnica', t ->> 'dispositivo',
      array(select jsonb_array_elements_text(t -> 'tags')), ids_materias, ids_topicos
    );
  end loop;

  -- Termos que já existiam: ganham as matérias e os tópicos do edital novo.
  for t in select * from jsonb_array_elements(vinculos) loop
    select coalesce(array_agg(id), '{}') into ids_materias from public.materias
    where user_id = uid and nome in (select jsonb_array_elements_text(t -> 'materias'));
    select coalesce(array_agg(tp.id), '{}') into ids_topicos
    from public.topicos tp
    join public.materias mt on mt.id = tp.materia_id
    where tp.user_id = uid
      and exists (
        select 1 from jsonb_array_elements(t -> 'topicos') par
        where par ->> 0 = mt.nome and par ->> 1 = tp.nome
      );
    update public.termos tr
    set materia_ids = array(
          select distinct x from unnest(tr.materia_ids || ids_materias) x
          where exists (select 1 from public.materias mm where mm.id = x)
        ),
        topico_ids = array(select distinct x from unnest(tr.topico_ids || ids_topicos) x)
    where tr.user_id = uid and lower(tr.termo) = lower(t ->> 'termo');
  end loop;

  -- "Não confundir com", nas duas direções.
  for p in select * from jsonb_array_elements(pares) loop
    select id into a from public.termos where user_id = uid and lower(termo) = lower(p ->> 0) limit 1;
    select id into b from public.termos where user_id = uid and lower(termo) = lower(p ->> 1) limit 1;
    if a is not null and b is not null and a <> b then
      insert into public.termos_relacionados (user_id, termo_id, relacionado_id)
      values (uid, a, b), (uid, b, a)
      on conflict do nothing;
    end if;
  end loop;

  update public.configuracoes set termos_2022 = true where user_id = uid;
end;
$$;

-- ---------------------------------------------------------------------------
-- Uma chamada só, na ordem certa. O app chama esta função ao abrir.
-- ---------------------------------------------------------------------------

create or replace function public.preparar_caderno()
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  perform public.semear_edital();
  perform public.atualizar_edital_2022();
  -- Etapas do 0008: rodar este arquivo de novo não as desliga.
  if to_regprocedure('public.revisar_edital_2022()') is not null then
    perform public.revisar_edital_2022();
  end if;
  perform public.semear_termos();
  perform public.semear_termos_2022();
  if to_regprocedure('public.semear_termos_2022b()') is not null then
    perform public.semear_termos_2022b();
  end if;
end;
$$;

revoke execute on function public.edital_tjdft_2022() from public, anon;
revoke execute on function public.semear_edital() from public, anon;
revoke execute on function public.atualizar_edital_2022() from public, anon;
revoke execute on function public.semear_termos_2022() from public, anon;
revoke execute on function public.preparar_caderno() from public, anon;
grant execute on function public.edital_tjdft_2022() to authenticated;
grant execute on function public.semear_edital() to authenticated;
grant execute on function public.atualizar_edital_2022() to authenticated;
grant execute on function public.semear_termos_2022() to authenticated;
grant execute on function public.preparar_caderno() to authenticated;
